INSERT INTO film_feedback (id, user_id, film_id, title, text, rating) VALUES
('8a9e0f1a-2b3c-4d5e-6f7a-8b9c0d1e2f3d', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890', '8a9e0f1a-2b3c-4d5e-6f7a-8b9c0d1e2f3a', 'Классика нуара', 'Прекрасный образец жанра! Напряженный сюжет, отличная актерская игра и атмосфера, которая держит до самого конца.', 9),
('8a9e0f1a-2b3c-4d5e-6f7a-8b9c0d1e2f3e', 'b2c3d4e5-f6a7-8901-bcde-f23456789012', '8a9e0f1a-2b3c-4d5e-6f7a-8b9c0d1e2f3a', 'Неожиданная развязка', 'Фильм держит в напряжении до последней минуты. Главная героиня вызывает смешанные чувства - то симпатию, то подозрение.', 8);


INSERT INTO film_feedback (id, user_id, film_id, title, text, rating) VALUES
('9a0f1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4e', 'c3d4e5f6-a7b8-9012-cdef-345678901234', '9a0f1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4b', 'Шедевр социальной сатиры', 'Блестящая критика медиа и общества потребления. Актуально даже сегодня! Том Хэнкс великолепен в роли циничного журналиста.', 10),
('9a0f1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4f', 'd4e5f6a7-b8c9-0123-def4-456789012345', '9a0f1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4b', 'Мрачно и реалистично', 'Фильм показывает, на что способны люди ради славы и денег. Отличная игра актеров и пронзительный сюжет.', 9);

