('647fc10b-58cc-0372-8567-0e02b2c3d557', '9f4e7a7c-8c5a-4e5a-9f3e-6e8a9b9c8d7e', '6e7f8a9b-0c1d-2e3f-4a5b-6c7d8e9f0a1b', 'Альфред Пенниуорт', 'Дворецкий и наставник Брюса Уэйна'),
