INSERT INTO compilation (id, title, description, icon) VALUES
-- 1. Шедевры кинематографа
('cc000001-0000-0000-0000-000000000001', 'Шедевры кинематографа', 'Фильмы, получившие высшие оценки от зрителей и критиков. Классика, которую стоит посмотреть каждому.', 'compilations/pic1.png'),

-- 2. Выбор редакции
('cc000002-0000-0000-0000-000000000002', 'Выбор редакции', 'Эксклюзивная подборка от нашей команды — картины, изменившие кинематограф.', 'compilations/pic2.png'),

-- 3. Золотой фонд советского кино
('cc000003-0000-0000-0000-000000000003', 'Золотой фонд советского кино', 'Легендарные советские фильмы — от лирических комедий до военных драм. Картины, ставшие символами эпохи и народной любви.', 'compilations/pic3.png'),

-- 4. Мировой калейдоскоп
('cc000004-0000-0000-0000-000000000004', 'Мировой калейдоскоп', 'Самые яркие и культурно значимые картины со всего света: от европейского артхауса до азиатских шедевров.', 'compilations/pic4.png'),

-- 5. Супергерои
('cc000005-0000-0000-0000-000000000005', 'Супергерои', 'Динамичные истории о людях со сверхспособностями, которые сражаются со злом, спасают мир и вдохновляют миллионы зрителей.', 'compilations/pic5.png'),

-- 6. Лауреаты мировых кинофестивалей
('cc000006-0000-0000-0000-000000000006', 'Лауреаты мировых кинофестивалей', 'Победители и номинанты крупнейших кинофестивалей. Выдающиеся работы, признанные мировыми критиками.', 'compilations/pic6.png');

