INSERT INTO film (id, title, original_title, cover, poster,
                 short_description, description, age_category,
                 budget, worldwide_fees, year, country_id, genre_id,
                 slogan, duration, release_date)
VALUES
  ('b5de9741-3728-4477-a43a-8dfbf731d736', 'Лиззи Магуайр', 'The Lizzie McGuire Movie', 'films/pic77.webp', 'posters/pic77.webp', 'Лиззи едет в Рим, где ее принимают за поп-звезду. Финальные похождения школьницы в исполнении Хилари Дафф', 'Тринадцатилетняя школьница Лиззи Магуайер и ее приятели Гордо, Кейт и Эсан собираются оттянуться по полной программе во время их поездки с классом в Италию.

Но там случается весьма неожиданное происшествие: девочку ошибочно принимают за итальянскую поп-звезду Изабеллу, да к тому же девушка влюбляется в бывшего дружка Изабеллы Паоло. Когда родители Лизи обо всем узнают, они вместе с ее братом Мэттом срочно вылетают в Италию.

Но Лиззи уже не та закомплексованная девочка-подросток, кем была раньше, она до такой степени вжилась в роль певицы, что и на самом деле стала самой настоящей звездой.', '12+', 20000000, 10000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Lizze McGuire goes to Rome.', 94, '2003-06-01'),
  ('7d134e55-49ac-4648-9319-d4541bfc64a4', 'Матрица', 'The Matrix', 'films/pic78.webp', 'posters/pic78.webp', 'Хакер Нео узнает, что его мир — виртуальный. Выдающийся экшен, доказавший, что зрелищное кино может быть умным', 'Жизнь Томаса Андерсона разделена на две части: днём он — самый обычный офисный работник, получающий нагоняи от начальства, а ночью превращается в хакера по имени Нео, и нет места в сети, куда он бы не смог проникнуть. Но однажды всё меняется. Томас узнаёт ужасающую правду о реальности.', '18+', 5000000, 10000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'Добро пожаловать в реальный мир', 136, '1999-06-01'),
  ('7fc96be9-ec6f-4778-9943-a87d61f02887', 'Клад', 'Holes', 'films/pic79.webp', 'posters/pic79.webp', 'Стэнли отбывает наказание в лагере, где все зачем-то роют ямы. Юный Шайа ЛаБаф в оригинальной семейной комедии', 'Стэнли арестован по ложному обвинению в краже кроссовок и отправлен в трудовой лагерь, расположенный в техасской пустыне. Воспитатели «закаляют характер» подростков странным наказанием. Ребята копают ямы в иссушенной земле, но не знают, что их на самом деле используют для раскопок таинственного клада. Однако Стэнли удается раскрыть загадочную связь между сокровищами и проклятием, тяготеющим долгие годы над его семьей…', '12+', 100000000, 800000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Кто ищет, тот всегда найдёт', 117, '2003-06-01'),
  ('53666f9d-bc9f-4c98-8224-c3923b33ee19', 'Управление гневом', 'Anger Management', 'films/pic80.webp', 'posters/pic80.webp', 'Тихоня Дэйв проходит терапию у доктора Бадди — и это сущее наказание. Джек Николсон учит жизни Адама Сэндлера', 'Скромному клерку отчаянно не везет. Парня по обвинению в нападении на бортпроводницу приговаривают к лечению у психиатра. Но верно говорят, что большинство психиатров сами немного безумны. Или сильно не в себе...', '18+', 50000000, 500000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Let the healing begin', 106, '2003-06-01'),
  ('c0caad3d-cf0c-4407-a336-377aabe69128', 'Афера', 'Confidence', 'films/pic81.webp', 'posters/pic81.webp', 'Чтобы уладить конфликт с мафиози, аферист должен обокрасть его конкурента. Триллер с Эдвардом Бернсом', 'Джейк Вига – хитроумный и обаятельный мошенник. Последняя афера Джейка привела к тому, что его дорожки пересеклись с мафией – при помощи своей команды он лишил нескольких тысяч долларов Лайонела Долби, – счетовода эксцентричного мафиозного босса Уинстона Кинга по прозвищу «Король».

Мафия шутить не любит, а любит выбивать долги из тех, кто пытается ее надуть. Чтобы сохранить жизнь и расквитаться с долгами, Джейку приходится устроить новую, еще более изощренную аферу – сложнейшую схему, в которой требуется «творческий подход к бухгалтерии».

Неожиданные помехи появляются одна за другой: палки в колеса Джейку вставляют его старый враг, агент ФБР Гюнтер Бутан, Трэвис, правая рука «Короля» и хитроумная карманщица Лили на которую Джейк успел положить глаз...', '18+', 1000000, 1000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Это не про деньги, это про ДЕНЬГИ!!!', 97, '2003-06-01'),
  ('3277508f-8fca-46b7-acca-67f21959126e', 'Телефонная будка', 'Phone Booth', 'films/pic82.webp', 'posters/pic82.webp', 'Стю попадает под прицел снайпера посреди Нью-Йорка. Колин Фаррелл в одном из лучших триллеров Джоэла Шумахера', 'Один телефонный звонок может изменить всю жизнь человека или даже оборвать ее. Герой фильма Стью Шеферд становится пленником телефонной будки.

Что вы сделаете, если услышите, как в телефонной будке зазвонил телефон? Скорее всего, инстинктивно поднимете трубку, хотя прекрасно знаете, что кто-то просто ошибся номером. Вот и Стью кажется, что на звонок надо обязательно ответить, а в результате он оказывается втянутым в чудовищную игру. «Только положи трубку, и ты – труп», – говорит ему невидимый собеседник.', '18+', 80000000, 160000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Линия жизни на линии огня', 81, '2002-06-01'),
  ('85a73928-60d8-478f-af5a-cb23b4460059', 'Рекрут', 'The Recruit', 'films/pic83.webp', 'posters/pic83.webp', 'Американская разведка вербует талантливого программиста. Триллер с Аль Пачино в роли опытного агента ЦРУ', 'Джеймс Клэйтон - студент и опытный хакер. Он привлекает внимание спецслужб, и его вербуют в ЦРУ, упоминая таинственное исчезновение его отца в 90-х. Джеймс обучается у Уолтера Бёрка. Он отлично сдает все тесты, кроме последнего. Так он становится агентом без прикрытия и получает задание: найти «крота», который похищает опасный вирус из Лэнгли.', '18+', 10000000, 30000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Trust. Betrayal. Deception. In the C.I.A. nothing is what it seems.', 115, '2003-06-01'),
  ('19e0566c-fe33-498e-8203-6ae908c83c2d', 'Разыскиваются в Малибу', 'Malibu''s Most Wanted', 'films/pic84.webp', 'posters/pic84.webp', 'Не стоит ненавидеть его за то, кем он является. Или кем он не является. Все, чем хочет заниматься Брэд - или Би-рэд - разъезжать со своими дружками по Малибу и вести себя, как самый крутой черный рэппер в округе.

Но все вокруг знают, что паренек, лихо читающий рэп, родом из респектабельного квартала Малибу. И отец Брэда, Билл Глакман, кандидат в губернаторы, серьезно боится, что увлечение Би-рэда «черной» культурой может разнести в пух и прах его предвыборную кампанию.', 'Не стоит ненавидеть его за то, кем он является. Или кем он не является. Все, чем хочет заниматься Брэд - или Би-рэд - разъезжать со своими дружками по Малибу и вести себя, как самый крутой черный рэппер в округе.

Но все вокруг знают, что паренек, лихо читающий рэп, родом из респектабельного квартала Малибу. И отец Брэда, Билл Глакман, кандидат в губернаторы, серьезно боится, что увлечение Би-рэда «черной» культурой может разнести в пух и прах его предвыборную кампанию.', '12+', 50000000, 150000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'cdf278db-e4f7-b2cf-f7f0-0f0afe4dc0f2', 'Ever feel like you don''t belong?', 86, '2003-06-01'),
  ('805810d8-cc0f-4d5e-968a-d4baf2232bcf', 'Тупой и еще тупее тупого: Когда Гарри встретил Ллойда', 'Dumb and Dumberer: When Harry Met Lloyd', 'films/pic85.webp', 'posters/pic85.webp', 'Как же встретились два героя-недоумка Гарри и Ллойд, известные по фильму «Тупой и еще тупее»? Оба несколько лет не ходили в школу, а учились на дому. Пришло время отправляться в школу, и прямо на улице Гарри и Ллойд столкнулись лбами...

А в это время школьный директор Коллинз и мисс Хеллер, буфетчица-официантка школьной столовой, задумали провернуть аферу - получить благотворительную премию в сто тысяч долларов за организацию класса для умственно отсталых. Злоумышленники решили создать липов...', 'Как же встретились два героя-недоумка Гарри и Ллойд, известные по фильму «Тупой и еще тупее»? Оба несколько лет не ходили в школу, а учились на дому. Пришло время отправляться в школу, и прямо на улице Гарри и Ллойд столкнулись лбами...

А в это время школьный директор Коллинз и мисс Хеллер, буфетчица-официантка школьной столовой, задумали провернуть аферу - получить благотворительную премию в сто тысяч долларов за организацию класса для умственно отсталых. Злоумышленники решили создать липовый класс. Два кандидата в спецкласс нашлись сразу - Гарри и Ллойд, а они разыскали остальных...', '16+', 80000000, 640000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'Тупой с первого взгляда', 85, '2003-06-01'),
  ('08557914-9df3-4473-bc24-e1edbe098dde', 'Эквилибриум', 'Equilibrium', 'films/pic86.webp', 'posters/pic86.webp', 'Агент идет против системы, которая подавляет эмоции. Стильная антиутопия с Кристианом Бэйлом', 'В будущем люди лишены возможности выражать эмоции. Это цена, которую человечество платит за устранение из своей жизни войны. Теперь книги, искусство и музыка находятся вне закона, а любое чувство — преступление, наказуемое смертью.

Для приведения в жизнь существующего правила используется принудительное применение лекарства прозиум. Правительственный агент Джон Престон борется с теми, кто нарушает правила. В один прекрасный момент он забывает принять очередную дозу лекарства, и с ним происходит духовное преображение, что приводит его к конфликту не только с режимом, но и с самим собой.', '18+', 200000000, 1000000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Мир, где эмоции караются смертью', 107, '2002-06-01'),
  ('473ff0eb-e89b-484f-b1d3-1560e218dedc', 'Дежурный папа', 'Daddy Day Care', 'films/pic87.webp', 'posters/pic87.webp', 'Потерявшие работу папаши открывают детский сад на дому. Феерический дуэт Эдди Мёрфи и Джеффа Гарлина', 'Чарли и Фила увольняют с работы в крупной корпорации. Теперь им самим придётся сидеть со своими сыновьями, так как оплачивать счета дорогостоящего детского центра уже не на что. Промучившись пару недель со своими отпрысками, папаши так увлекаются этим делом, что решают поставить дело на деловые рельсы и открывают новый центр дневного пребывания для детей. 

Чарли и Филл находят всё новые и новые нетрадиционные и забавные способы воспитательного воздействия на малышей, и центр «Дежурный папа» становится всё более популярным. Почувствовав жёсткое соперничество со стороны усатых няней, директриса дорогого детского центра решает выжить конкурентов-новичков из бизнеса.', '6+', 300000000, 600000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'D-Day Is Coming', 89, '2003-06-01'),
  ('833df4cf-fc37-4e42-9b17-7642a39c2085', 'Пуленепробиваемый', 'Bulletproof Monk', 'films/pic88.webp', 'posters/pic88.webp', 'Монах-мастер боевых искусств охраняет древний свиток — артефакт, содержащий ключ к безграничной власти. Монаху нужно найти следующего хранителя, и поиски приводят его в Америку. Согласно древнему пророчеству и к изумлению Монаха его преемником оказывается обаятельный хулиган по имени Кар. Пока Монах обучает Кара, обоим приходится защищать свиток от одержимого жаждой власти человека, который гоняется за ним 60 лет.', 'Монах-мастер боевых искусств охраняет древний свиток — артефакт, содержащий ключ к безграничной власти. Монаху нужно найти следующего хранителя, и поиски приводят его в Америку. Согласно древнему пророчеству и к изумлению Монаха его преемником оказывается обаятельный хулиган по имени Кар. Пока Монах обучает Кара, обоим приходится защищать свиток от одержимого жаждой власти человека, который гоняется за ним 60 лет.', '12+', 50000000, 100000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '3c8df0a2-5d9e-4936-b8f7-8b91f5439f33', 'To fulfill the prophecy, he must find the one to take his place', 104, '2003-06-01'),
  ('9fef9756-fb4a-4e47-b5a9-020ca93aed70', 'Властелин колец: Две крепости', 'The Lord of the Rings: The Two Towers', 'films/pic89.webp', 'posters/pic89.webp', 'Голлум ведет хоббитов в Мордор, а великие армии готовятся к битве. Вторая часть трилогии, два «Оскара»', 'Братство распалось, но Кольцо Всевластья должно быть уничтожено. Фродо и Сэм вынуждены довериться Голлуму, который взялся провести их к вратам Мордора. Громадная армия Сарумана приближается: члены братства и их союзники готовы принять бой. Битва за Средиземье продолжается.', '12+', 150000000, 1200000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Приключение продолжается', 179, '2002-06-01'),
  ('4797c46b-a290-4a40-a321-448c8a69f3e4', 'Играй как Бекхэм', 'Bend It Like Beckham', 'films/pic90.webp', 'posters/pic90.webp', 'Индианка мечтает стать футболисткой вопреки воле родителей. Блестящая комедия о борьбе за мечту с Кирой Найтли', 'Джесс только 18, но она твердо знает, что сделает ее счастливой: футбольная карьера как у знаменитого игрока «Манчестер Юнайтед» Дэвида Бекхема. Пока она гоняет мяч в лондонском парке, доказывая соседским мальчишкам, что девушки играют в футбол не хуже, ее родители и многочисленные родственники, как и положено традиционной индийской семье, подыскивают для нее достойного мужа и строят планы о ее будущей карьере юриста. Однажды во время очередной разминки Джесс знакомится с Джулз, и та приглашает ее на тренировку в женскую футбольную секцию.', '18+', 5000000, 40000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Живи на полную! Люби без памяти!', 112, '2002-06-01'),
  ('216af27f-31c2-40eb-ad78-0f68301df938', 'Цыпочка', 'The Hot Chick', 'films/pic91.webp', 'posters/pic91.webp', 'Школьница и невзрачный мужчина меняются телами. Комедия с Робом Шнайдером и Рэйчел МакАдамс на заре карьеры', 'Популярная, но неприятная в общении старшеклассница Джессика однажды утром просыпается в теле 30-летнего мужчины с не самой привлекательной внешностью. Девушка отправляется на поиски своего тела, и это приключение помогает ей увидеть себя со стороны и понять, насколько поверхностной и недалёкой она была.', '18+', 50000000, 100000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8f3e4f27-0ff9-fefb-3ffc-2c2f0f6f82f4', 'Однажды она проснулась не в себе... В буквальном смысле!', 104, '2002-06-01'),
  ('1c74098b-6a76-42cb-928c-2da210fc437a', 'Матрица: Революция', 'The Matrix Revolutions', 'films/pic92.webp', 'posters/pic92.webp', 'Для Нео пришло время исполнить пророчество и дать бой Матрице. Финал трилогии с эпической битвой людей и машин', 'Пока армия машин пытается уничтожить Зион, его жители из последних сил держат оборону.', '18+', 150000000, 1200000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'Все, что имеет начало, имеет и конец', 129, '2003-06-01'),
  ('619efe75-ce35-499b-b0db-24faec9d2451', 'Любовь с уведомлением', 'Two Weeks Notice', 'films/pic93.webp', 'posters/pic93.webp', 'Джордж Уэйд и шага не может сделать без Люси Келсон, работающей главным консультантом в его корпорации. Однако обращается он с ней скорее как с няней, а не как с блестящим юристом, окончившим Гарвард. По прошествии года все это надоедает Люси, и она решает уволиться. Джордж соглашается ее отпустить, но с одним условием — она должна найти себе достойную замену...', 'Джордж Уэйд и шага не может сделать без Люси Келсон, работающей главным консультантом в его корпорации. Однако обращается он с ней скорее как с няней, а не как с блестящим юристом, окончившим Гарвард. По прошествии года все это надоедает Люси, и она решает уволиться. Джордж соглашается ее отпустить, но с одним условием — она должна найти себе достойную замену...', '16+', 20000000, 60000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Он стремился к своей мечте, а она была рядом', 101, '2002-06-01'),
  ('8013c0cd-4c14-4778-8c67-5f8ffd163e4b', 'Ограбление по-итальянски', 'The Italian Job', 'films/pic94.webp', 'posters/pic94.webp', 'Банда грабителей решает отомстить предателю и сорвать большой куш. Ремейк криминальной комедии 1969 года', 'Джон Бриджер всегда умел спланировать идеальное ограбление. Вместе со своей командой опытных бандитов он провернул не одно дело, но теперь решил уйти на покой. Впереди у Бриджера последнее задание: кража золотых слитков, в которой принимают участие инсайдер Стив, водитель Роб, взрыватель Левое ухо, технарь Лайл и Чарли - верный друг Бриджера и второй «планировщик» в их команде. Ограбление, изящное и быстрое, было разыграно как по нотам, но после его завершения веселье преступников было омрачено предательством...', '16+', 300000000, 150000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Хватай. Убегай. Отомсти', 111, '2003-06-01'),
  ('25e2c175-cf11-4202-96b5-8315ade95d25', 'Терминатор 3: Восстание машин', 'Terminator 3: Rise of the Machines', 'films/pic95.webp', 'posters/pic95.webp', 'Джон Коннор противостоит новому киборгу и техно-апокалипсису. В режиссерском кресле — Джонатан Мостоу', 'Прошло десять лет с тех пор, как Джон Коннор помог предотвратить Судный День и спасти человечество от массового уничтожения. Теперь ему 25, Коннор не живет «как все» - у него нет дома, нет кредитных карт, нет сотового телефона и никакой работы.

Его существование нигде не зарегистрировано. Он не может быть прослежен системой Skynet - высокоразвитой сетью машин, которые когда-то попробовали убить его и развязать войну против человечества. Пока из теней будущего не появляется T-X - Терминатрикс, самый сложный киборг-убийца Skynet.

Посланная назад сквозь время, чтобы завершить работу, начатую её предшественником, T-1000, эта машина так же упорна, как прекрасен её человеческий облик. Теперь единственная надежда Коннору выжить - Терминатор, его таинственный прежний убийца. Вместе они должны одержать победу над новыми технологиями T-X и снова предотвратить Судный День...', '18+', 150000000, 150000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'The Machines Will Rise', 109, '2003-06-01'),
  ('fa277412-ab06-4c14-b65a-df9b3efb11a7', '25-й час', '25th Hour', 'films/pic96.webp', 'posters/pic96.webp', 'Наркоторговец проводит с друзьями последние сутки перед тюрьмой. Драма Спайка Ли по книге Дэвида Бениоффа', 'В фильме описывается последний день свободной жизни молодого бруклинца Монти Брогана (Эдвард Нортон), осужденного на семь лет тюрьмы за торговлю наркотиками. Оставшиеся 24 часа он проводит в компании своих родных, друзей, деловых партнеров и любимой девушки Натурель.

Монти, мечтавший в свое время стать пожарным, но в итоге ступивший на роковую стезю наркодилера, прощается с прошлым и пытается переосмыслить свою жизнь...', '18+', 1000000, 5000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'This life was so close to never happening', 135, '2002-06-01'),
  ('80a80c3f-2789-43b9-94ae-349b6d2d685b', 'Звездный путь: Возмездие', 'Star Trek: Nemesis', 'films/pic97.webp', 'posters/pic97.webp', 'Клон капитана Пикара намерен уничтожить Землю с помощью супероружия. В роли злодея Шинзона — Том Харди', 'После свадьбы командира Уильяма Райкера и советника Дианы Трой экипаж корабля «Энтерпрайз» обнаруживает позитронный сигнал на одной из планет около нейтральной зоны, где они находят B-4 — менее совершенный, чем Дейта, прототип андроида, созданного доктором Сунгом.

Эта загадка остается неразгаданной, так как в то же время адмирал Джейнвей приказывает «Энтерпрайзу» отправиться к Ромулу, где сенат был свергнут в результате государственного переворота Шинзоном и его последователями. По прибытии на Ромул «Энтерпрайз» обнаруживает не только самый мощный из всех встреченных ими кораблей, но и страшную тайну, касающуюся нового лидера Ромуланской империи, который планирует использовать смертельное оружие для уничтожения всего живого на главной планете Федерации — Земле.', '18+', 200000000, 100000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Последнее путешествие поколения начинается...', 116, '2002-06-01'),
  ('0d033897-eb4e-4e1c-8afe-e340136532e3', 'Гарри Поттер и узник Азкабана', 'Harry Potter and the Prisoner of Azkaban', 'films/pic98.webp', 'posters/pic98.webp', 'Беглый маг, тайны прошлого и путешествия во времени. В третьей части поттерианы Альфонсо Куарон сгущает краски', 'Гарри, Рон и Гермиона возвращаются на третий курс школы чародейства и волшебства Хогвартс. На этот раз они должны раскрыть тайну узника, сбежавшего из тюрьмы Азкабан, чье пребывание на воле создает для Гарри смертельную опасность.', '12+', 100000000, 1000000000, 2004, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'Всё изменится', 142, '2004-06-01'),
  ('e082d960-5545-42b6-ba83-f7d6f7679b53', 'Двойной форсаж', '2 Fast 2 Furious', 'films/pic99.webp', 'posters/pic99.webp', 'Брайан и Роман по заданию ФБР разоблачают крупного драгдилера. Стильный сиквел с крутыми тачками и Евой Мендес', 'Бывший полицейский Брайан О`Коннер с напарником Романом Пирсом собирается перевезти крупную сумму грязных денег известного мафиози Картера Верона. Но на самом деле эта работа является только прикрытием для Брайана, который вместе с тайным агентом Моникой Фуэнтес должен уличить изворотливого преступника.', '12+', 50000000, 50000000, 2003, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Какую скорость ты выдержишь?', 107, '2003-06-01'),
  ('85177105-2ca0-41a6-929d-5755e660d987', 'Поймай меня, если сможешь', 'Catch Me If You Can', 'films/pic100.webp', 'posters/pic100.webp', 'Виртуозный аферист годами водит за нос ФБР. Хит Стивена Спилберга по реальным событиям с Леонардо ДиКаприо', 'Фрэнк Эбегнейл успел поработать врачом, адвокатом и пилотом на пассажирской авиалинии – и все это до достижения полного совершеннолетия в 21 год. Мастер в обмане и жульничестве, он также обладал искусством подделки документов, что в конечном счете принесло ему миллионы долларов, которые он получил по фальшивым чекам.

Агент ФБР Карл Хэнрэтти отдал бы все, чтобы схватить Фрэнка и привлечь к ответственности за свои деяния, но Фрэнк всегда опережает его на шаг, заставляя продолжать погоню.', '18+', 100000000, 200000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'cdf278db-e4f7-b2cf-f7f0-0f0afe4dc0f2', 'Правдивая история о реальном преступнике', 141, '2002-06-01'),
  ('5aea22b9-18b2-4ed8-a137-87df2d0b7eb5', 'Крестный отец', 'The Godfather', 'films/pic101.webp', 'posters/pic101.webp', 'В семье крупного нью-йоркского мафиози наметился кризис. Революция в гангстерском кино и начало большого эпоса', 'Криминальная сага, повествующая о нью-йоркской сицилийской мафиозной семье Корлеоне. Фильм охватывает период 1945-1955 годов.

Глава семьи, Дон Вито Корлеоне, выдаёт замуж свою дочь. В это время со Второй мировой войны возвращается его любимый сын Майкл. Майкл, герой войны, гордость семьи, не выражает желания заняться жестоким семейным бизнесом. Дон Корлеоне ведёт дела по старым правилам, но наступают иные времена, и появляются люди, желающие изменить сложившиеся порядки. На Дона Корлеоне совершается покушение.', '18+', 80000000, 160000000, 1972, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Настоящая сила не может быть дана, она может быть взята...', 175, '1972-06-01'),
  ('5c95fa96-58d2-4f67-ab6d-8c8ef84aef9b', 'Побег из Шоушенка', 'The Shawshank Redemption', 'films/pic102.webp', 'posters/pic102.webp', 'Несправедливо осужденный банкир готовит побег из тюрьмы. Тим Роббинс в выдающейся экранизации Стивена Кинга', 'Бухгалтер Энди Дюфрейн обвинён в убийстве собственной жены и её любовника. Оказавшись в тюрьме под названием Шоушенк, он сталкивается с жестокостью и беззаконием, царящими по обе стороны решётки. Каждый, кто попадает в эти стены, становится их рабом до конца жизни. Но Энди, обладающий живым умом и доброй душой, находит подход как к заключённым, так и к охранникам, добиваясь их особого к себе расположения.', '18+', 80000000, 40000000, 1994, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Страх - это кандалы. Надежда - это свобода', 142, '1994-06-01'),
  ('c4de4c96-bc2c-4cc8-b3d6-0040c5d77f30', 'Крестный отец 2', 'The Godfather: Part II', 'films/pic103.webp', 'posters/pic103.webp', 'Юность Вито Корлеоне и первые шаги его сына Майкла во главе клана — сразу и приквел, и сиквел. Шесть «Оскаров»', 'Для дона Корлеоне и его сына не существует моральных преград на пути к достижению целей. Они превращают мафию, построенную по патриархальным сицилийским законам, в весьма прагматичную, жесткую корпорацию, плавно интегрируя её в большой бизнес Америки.', '18+', 200000000, 600000000, 1974, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'All the power on earth can''t change destiny.', 202, '1974-06-01'),
  ('d6687596-e12e-4ff0-a287-f6c29a32aeb5', 'Властелин колец: Братство кольца', 'The Lord of the Rings: The Fellowship of the Ring', 'films/pic104.webp', 'posters/pic104.webp', 'Фродо Бэггинс отправляется спасать Средиземье. Первая часть культовой фэнтези-трилогии Питера Джексона', 'Сказания о Средиземье — это хроника Великой войны за Кольцо, длившейся не одну тысячу лет. Тот, кто владел Кольцом, получал неограниченную власть, но был обязан служить злу. 
Тихая деревня, где живут хоббиты. Придя на 111-й день рождения к своему старому другу Бильбо Бэггинсу, волшебник Гэндальф начинает вести разговор о кольце, которое Бильбо нашел много лет назад. Это кольцо принадлежало когда-то темному властителю Средиземья Саурону, и оно дает большую власть своему обладателю. Теперь Саурон хочет вернуть себе власть над Средиземьем. Бильбо отдает Кольцо племяннику Фродо, чтобы тот отнёс его к Роковой Горе и уничтожил.', '12+', 50000000, 500000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Power can be held in the smallest of things...', 178, '2001-06-01'),
  ('f13ccadf-3d0a-43e7-aa28-a25655e2d494', 'Список Шиндлера', 'Schindler''s List', 'films/pic105.webp', 'posters/pic105.webp', 'История немецкого промышленника, спасшего тысячи жизней во время Холокоста. Драма Стивена Спилберга', 'Фильм рассказывает реальную историю загадочного Оскара Шиндлера, члена нацистской партии, преуспевающего фабриканта, спасшего во время Второй мировой войны почти 1200 евреев.', '18+', 300000000, 1500000000, 1993, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Этот список - жизнь', 195, '1993-06-01'),
  ('376da0a6-a810-4c51-b869-a84b196f993b', 'Касабланка', 'Casablanca', 'films/pic106.webp', 'posters/pic106.webp', 'Циник с разбитым сердцем встречает любимую во время войны. Шедевр с Хамфри Богартом и Ингрид Бергман', 'Оставивший родину американец Рик Блейн, владелец игорного клуба в Касабланке, встречается с покинувшей его несколько лет назад возлюбленной Ильзой, которая приехала в город вместе со своим мужем — борцом антифашистского сопротивления Виктором Лазло. По их следу идут немцы, и Ильза пытается упросить Рика отдать принадлежащие ему важные документы, которые позволят Виктору бежать из Касабланки и продолжить борьбу.', '12+', 1000000, 2000000, 1942, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Where Love Cuts as Deep as a Dagger!', 103, '1942-06-01'),
  ('1a49021f-9f4b-4c82-bf72-5bfa5fd5bf23', 'Гражданин Кейн', 'Citizen Kane', 'films/pic107.webp', 'posters/pic107.webp', 'Что скрывает загадочный медиамагнат? Один из величайших фильмов всех времен', 'В шикарном поместье умирает газетный магнат Чарльз Фостер Кейн, роняя лишь одно слово: «Роузбад». Смерть Кейна вызывает бурную реакцию в обществе, и группа журналистов берётся узнать, кем же он был на самом деле, что он пережил за свою долгую, полную взлётов и падений, жизнь... И что всё-таки значит «Роузбад»?', '12+', 150000000, 1200000000, 1941, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Radio''s Most Dynamic Artist . . The Man At Whose Voice A Nation Trembled . . . Now the screen''s most exciting NEW star ! ORSON WELLES in the picture Hollywood said he''d never make', 119, '1941-06-01'),
  ('f3b49da6-f400-4f2a-92a4-90136497dd1c', 'Семь самураев', 'Shichinin no samurai', 'films/pic108.webp', 'posters/pic108.webp', 'Обедневшие воины защищают крестьян от бандитов в обмен на еду. Шедевр Акиры Куросавы, изменивший кинематограф', 'Япония, XVI век. В стране полыхает гражданская война, повсюду орудуют банды разбойников и мародеров. Бедные крестьяне нанимают для защиты деревни семерых самураев, которые немного сплачивают раздробленных и малодушных селян в процессе подготовки и укрепления деревни.', '16+', 20000000, 100000000, 1954, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a15', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The Mighty Warriors Who Became the Seven National Heroes of a Small Town', 207, '1954-06-01'),
  ('59a7c04a-876b-409e-8993-417d8dca56a8', 'Звёздные войны: Эпизод 4 – Новая надежда', 'Star Wars', 'films/pic109.webp', 'posters/pic109.webp', 'Джедай и контрабандист помогают мятежнице бежать из плена. Начало эпической космической саги Джорджа Лукаса', 'Татуин. Планета-пустыня. Уже постаревший рыцарь Джедай Оби Ван Кеноби спасает молодого Люка Скайуокера, когда тот пытается отыскать пропавшего дроида. С этого момента Люк осознает свое истинное назначение: он один из рыцарей Джедай. В то время как гражданская война охватила галактику, а войска повстанцев ведут бои против сил злого Императора, к Люку и Оби Вану присоединяется отчаянный пилот-наемник Хан Соло, и в сопровождении двух дроидов, R2D2 и C-3PO, этот необычный отряд отправляется на поиски предводителя повстанцев – принцессы Леи. Героям предстоит отчаянная схватка с устрашающим Дартом Вейдером – правой рукой Императора и его секретным оружием – «Звездой Смерти».', '6+', 10000000, 5000000, 1977, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'Coming to your galaxy this summer.  (Teaser poster)', 121, '1977-06-01'),
  ('c08b87cd-c0e1-4c57-9336-c5da19914e9d', 'Доктор Стрейнджлав, или Как я научился не волноваться и полюбил атомную бомбу', 'Dr. Strangelove or: How I Learned to Stop Worrying and Love the Bomb', 'films/pic110.webp', 'posters/pic110.webp', 'Из-за безумного генерала США и СССР оказываются на грани ядерной войны. Абсурдистская комедия Стэнли Кубрика', 'Одержимый мыслью, что коммунисты намереваются украсть у американцев их «бесценные телесные соки», командир военно-воздушной базы генерал Джек Д. Риппер посылает эскадрилью бомбардировщиков с ядерным оружием бомбить СССР. Президент США Маффли пытается спасти положение — он собирает своих советников, включая доблестного генерала Тергидсона и прикованного к инвалидной коляске бывшего нацистского ученого доктора Стрейнджлава.', '12+', 50000000, 25000000, 1963, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'the hot-line suspense comedy', 95, '1963-06-01'),
  ('8aa37e17-0121-4ffb-a293-a235e8b5f6cf', 'Мементо', 'Memento', 'films/pic111.webp', 'posters/pic111.webp', 'Леонард ищет убийцу жены, но ему мешает амнезия. Виртуозный триллер, сделавший Кристофера Нолана суперзвездой', 'Леонард Шелби изысканно и дорого одет, ездит на новеньком «Ягуаре», но останавливается в дешевых мотелях. Он всеми силами пытается найти убийцу жены. Его проблема — редкая форма амнезии, потеря короткой памяти — помня все до убийства, он не помнит, что было 15 минут назад.', '18+', 1000000, 1000000, 2000, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Некоторые воспоминания лучше забыть', 113, '2000-06-01'),
  ('5a7186d8-c27b-410a-981c-4a4734cd2086', 'Пролетая над гнездом кукушки', 'One Flew Over the Cuckoo''s Nest', 'films/pic112.webp', 'posters/pic112.webp', 'Джек Николсон — запертый в психушке бунтарь, который борется с системой. По великому роману Кена Кизи', 'Рэндла Патрика Макмёрфи, патологического преступника и бунтаря, переводят из колонии в психиатрическую клинику, чтобы установить, является он душевнобольным или нет. В клинике он обнаруживает, что отделение контролирует хладнокровная, строгая и одержимая распорядком старшая медсестра Милдред Рэтчед. Макмёрфи намерен не подчиняться абсурдным, на его взгляд, правилам и одновременно повеселиться от души. Его бунтарская натура заражает других пациентов, но сестра Рэтчед решительно настроена пресечь это.', '18+', 50000000, 400000000, 1975, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'If he''s crazy, what does that make you?', 133, '1975-06-01'),
  ('ce0f7498-fc5b-4e02-9f2f-45239aafe995', 'Окно во двор', 'Rear Window', 'films/pic113.webp', 'posters/pic113.webp', 'Фотограф со сломанной ногой наблюдает через объектив за жизнью соседей. Вуайеристский триллер Альфреда Хичкока', 'Прикованный из-за сломанной ноги к инвалидному креслу фоторепортер от скуки подглядывает за соседями, живущими в его же доме, чьи окна выходят во внутренний двор. Постоянные наблюдения наталкивают его на мысль, что один из соседей ведет себя подозрительно.', '12+', 50000000, 25000000, 1954, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Suspense Of Screaming Proportions!', 112, '1954-06-01'),
  ('2c53a9cc-c630-474f-afd8-bf39aebcb89c', 'Звёздные войны: Эпизод 5 – Империя наносит ответный удар', 'Star Wars: Episode V - The Empire Strikes Back', 'films/pic114.webp', 'posters/pic114.webp', 'Юный Люк продолжает постигать Силу, но его ждет страшная тайна. Вторая часть оригинальной трилогии о джедаях', 'Борьба за Галактику обостряется в пятом эпизоде космической саги. Войска Императора начинают массированную атаку на повстанцев и их союзников.

Хан Соло и принцесса Лейя укрываются в Заоблачном Городе, в котором их и захватывает Дарт Вейдер, в то время как Люк Скайуокер находится на таинственной планете джунглей Дагоба.

Там Мастер - джедай Йода обучает молодого рыцаря навыкам обретения Силы. Люк даже не предполагает, как скоро ему придется воспользоваться знаниями старого Мастера: впереди битва с превосходящими силами Императора и смертельный поединок с Дартом Вейдером.', '12+', 1000000, 10000000, 1980, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'The battle continues...', 124, '1980-06-01'),
  ('261b14b4-d9ba-4674-bc77-97f6898878e8', 'Индиана Джонс: В поисках утраченного ковчега', 'Raiders of the Lost Ark', 'films/pic115.webp', 'posters/pic115.webp', 'Ироничный археолог ищет артефакт наперегонки с нацистами. Легендарный приключенческий фильм Стивена Спилберга', 'Известный археолог и специалист по оккультным наукам доктор Джонс получает опасное задание от правительства США. Он должен отправиться на поиски уникальной реликвии — священного Ковчега. Но Индиана и не подозревает, что аналогичный приказ уже получили тайные агенты Адольфа Гитлера.', '12+', 20000000, 20000000, 1981, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'Indiana Jones - the new hero from the creators of JAWS and STAR WARS', 115, '1981-06-01'),
  ('8fd0469d-f955-4228-80fd-5529ccd1ddf2', 'Подозрительные лица', 'The Usual Suspects', 'films/pic116.webp', 'posters/pic116.webp', 'Пятеро бандитов, сами того не зная, работают на фантомного злодея. Триллер-квест с двумя «Оскарами»', 'Если есть преступление, есть и мотив. Если проводится опознание, то по крайней мере есть один подозреваемый. Но это было необычное преступление. Пять преступников столкнулись в одном необычном месте и решили прокрутить одно дельце. Но некто более сильный и влиятельный, некто, чье имя пугает всех преступников мира, хочет, чтобы они поработали на него. Это не было обычным преступлением, и они — не просто подозрительные лица.', '18+', 200000000, 600000000, 1995, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Пятеро преступников. Опознание. Никаких совпадений', 106, '1995-06-01'),
  ('64f5bd6a-a80b-4ed1-a0dd-6fb59b878e01', 'Амели', 'Le Fabuleux destin d''Amélie Poulain', 'films/pic117.webp', 'posters/pic117.webp', 'Мечтательная чудачка пытается сделать окружающих людей счастливее. Волшебный французский ромком с Одри Тоту', 'Как полет крошечной мухи может вызвать где-то далеко мощный ураган, так и странные и, на первый взгляд, непонятные поступки тихой одинокой девушки, живущей в мире своих фантазий, могут навсегда изменить жизнь совершенно разных людей, подарив им счастье и раскрасив окружающий мир яркими красками. Эту девушку зовут Амели Пулен.', '18+', 20000000, 20000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Она изменит вашу жизнь', 122, '2001-06-01'),
  ('a8fc8f1f-ab5c-46a6-a105-493b6c01cbdc', 'Криминальное чтиво', 'Pulp Fiction', 'films/pic118.webp', 'posters/pic118.webp', 'Несколько связанных историй из жизни бандитов. Шедевр Квентина Тарантино, который изменил мировое кино', 'Двое бандитов Винсент Вега и Джулс Винфилд ведут философские беседы в перерывах между разборками и решением проблем с должниками криминального босса Марселласа Уоллеса.
В первой истории Винсент проводит незабываемый вечер с женой Марселласа Мией. Во второй Марселлас покупает боксёра Бутча Кулиджа, чтобы тот сдал бой. В третьей истории Винсент и Джулс по нелепой случайности попадают в неприятности.', '18+', 1000000, 2000000, 1994, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Just because you are a character doesn''t mean you have character', 154, '1994-06-01'),
  ('54603f50-5e73-4752-a244-eff96078be8b', 'На север через северо-запад', 'North by Northwest', 'films/pic119.webp', 'posters/pic119.webp', 'Однажды успешного рекламного агента Роджера Торнхилла ошибочно принимают за агента разведки Кэплана, которого никто не знает в лицо, и хотят его убрать. Обескураженный Роджер пытается бежать. В вагоне-ресторане поезда милая женщина по имени Ив помогает ему скрыться от преследователей...', 'Однажды успешного рекламного агента Роджера Торнхилла ошибочно принимают за агента разведки Кэплана, которого никто не знает в лицо, и хотят его убрать. Обескураженный Роджер пытается бежать. В вагоне-ресторане поезда милая женщина по имени Ив помогает ему скрыться от преследователей...', '12+', 5000000, 15000000, 1959, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'It''s love and murder at first sight!', 136, '1959-06-01'),
  ('ae3c1974-c7c2-4c83-b225-ea7cc50d3eff', 'Психо', 'Psycho', 'films/pic120.webp', 'posters/pic120.webp', 'Кто-то убивает девушек в одиноком мотеле. Эстетский черно-белый хоррор Альфреда Хичкока, ставший классикой', 'Мэрион Крэйн недовольна романом с разведенным мужчиной, который уделяет ей внимание только наездами. Поэтому девушка крадет на работе крупную сумму и в спешке бежит из города. Мэрион останавливается на ночь в мотеле, которым управляет Норман Бейтс — юноша, страдающий от гнёта своей горячо любимой, но деспотичной матери.', '18+', 200000000, 1000000000, 1960, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Фильм, который изменил кино навсегда', 109, '1960-06-01'),
  ('24daaef9-be46-47cd-8150-ce5a5157b701', 'Молчание ягнят', 'The Silence of the Lambs', 'films/pic121.webp', 'posters/pic121.webp', 'Интеллектуал-людоед помогает молодой сотруднице ФБР. Веха в жанре триллера — и гениальная игра Энтони Хопкинса', 'Психопат похищает и убивает молодых женщин по всему Среднему Западу. ФБР, уверенное, что все преступления совершены одним и тем же человеком, поручает агенту Клариссе Старлинг встретиться с заключенным-маньяком Ганнибалом Лектером, который мог бы помочь составить психологический портрет убийцы. Сам Лектер отбывает наказание за убийства и каннибализм. Он согласен помочь Клариссе лишь в том случае, если она попотчует его больное воображение подробностями своей личной жизни.', '18+', 300000000, 300000000, 1990, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'From the terrifying best seller', 118, '1990-06-01'),
  ('0621b7a1-d38f-47d3-8954-576cbf29d069', '12 разгневанных мужчин', '12 Angry Men', 'films/pic122.webp', 'posters/pic122.webp', 'Юношу обвиняют в убийстве собственного отца, ему грозит электрический стул. Двенадцать присяжных собираются, чтобы вынести вердикт: виновен или нет. С начала заседания почти все считают подсудимого виновным, и лишь только один из двенадцати позволил себе усомниться. И он решает убедить остальных в своей правоте.', 'Юношу обвиняют в убийстве собственного отца, ему грозит электрический стул. Двенадцать присяжных собираются, чтобы вынести вердикт: виновен или нет. С начала заседания почти все считают подсудимого виновным, и лишь только один из двенадцати позволил себе усомниться. И он решает убедить остальных в своей правоте.', '16+', 200000000, 1000000000, 1956, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'they have twelve scraps of paper... twelve chances to kill!', 96, '1956-06-01'),
  ('1851b1e3-461b-48a4-985e-17533ee7190e', 'Лоуренс Аравийский', 'Lawrence of Arabia', 'films/pic123.webp', 'posters/pic123.webp', 'Фильм рассказывает о легендарном герое Первой мировой войны - английском разведчике Т.Э. Лоуренсе, действовавшем среди арабских племен и возглавившем их в походе против турок.', 'Фильм рассказывает о легендарном герое Первой мировой войны - английском разведчике Т.Э. Лоуренсе, действовавшем среди арабских племен и возглавившем их в походе против турок.', '12+', 10000000, 80000000, 1962, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a18', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'After five years... the first motion picture from the creators of «The Bridge On The River Kwai.» Columbia Pictures presents The Sam Spiegel . David Lean Production of .....', 216, '1962-06-01'),
  ('b90174f0-56c5-4833-95f5-40525ae9d5c3', 'Эта замечательная жизнь', 'It''s a Wonderful Life', 'films/pic124.webp', 'posters/pic124.webp', 'Сможет ли ангел убедить отчаявшегося Джорджа, что он живет не зря? Сказочная горько-сладкая классика Голливуда', 'Джордж Бейли, житель небольшого провинциального городка, всегда хотел повидать мир, но обстоятельства не давали ему покинуть родные места. Он жертвовал собой ради других, копил каждый цент, чтобы содержать семью, брал взаймы и защищал городок от злого банкира Поттера. И вот, в канун Рождества, расстроенный бесчисленными проблемами и терзаемый мыслями, что лучше бы и вовсе не рождаться, Джордж решается на отчаянный поступок. Но именно в этот момент к нему приходит ангел, чтобы показать мужчине, какой была бы жизнь, если бы он не родился.', '12+', 200000000, 1600000000, 1947, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'They''re going steady...straight to your heart!', 130, '1947-06-01'),
  ('4dcd1f46-0678-4d89-8a33-14635285eee0', 'Хороший, плохой, злой', 'Il buono, il brutto, il cattivo', 'films/pic125.webp', 'posters/pic125.webp', 'Разгар Гражданской войны, Дикий Запад. По воле судьбы трое мужчин вынуждены объединить усилия в поисках украденного золота. Но совместная работа — не самое подходящее занятие для таких отъявленных бандитов. Компаньоны вскоре понимают, что в их дерзком и опасном путешествии по разоренной войной стране самое важное — никому не доверять и держать пистолет наготове.', 'Разгар Гражданской войны, Дикий Запад. По воле судьбы трое мужчин вынуждены объединить усилия в поисках украденного золота. Но совместная работа — не самое подходящее занятие для таких отъявленных бандитов. Компаньоны вскоре понимают, что в их дерзком и опасном путешествии по разоренной войной стране самое важное — никому не доверять и держать пистолет наготове.', '16+', 50000000, 100000000, 1966, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'cdf278db-e4f7-b2cf-f7f0-0f0afe4dc0f2', 'Для этих трех мужчин гражданская война - не ад, для них она - учебка!', 178, '1966-06-01')
ON CONFLICT (title, year) DO NOTHING;

