INSERT INTO film (id, title, original_title, cover, poster,
                 short_description, description, age_category,
                 budget, worldwide_fees, year, country_id, genre_id,
                 slogan, duration, release_date)
VALUES
  ('0be3c1c4-9a49-4aca-8b8b-798b34738065', 'Славные парни', 'Goodfellas', 'films/pic126.webp', 'posters/pic126.webp', 'Путь к власти легендарного мафиози Генри Хилла. Гангстерская классика Мартина Скорсезе с Робертом Де Ниро', 'История о Генри Хилле — начинающем гангстере, занимающемся грабежами вместе с подельниками Джими Конвеем и Томми Де Вито, которые с легкостью убивают любого, кто встаёт у них на пути.', '18+', 80000000, 640000000, 1990, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Тридцать лет из жизни мафии', 140, '1990-06-01'),
  ('2d513fa8-ed6b-479f-88cf-1380af9b54f4', 'Красота по-американски', 'American Beauty', 'films/pic127.webp', 'posters/pic127.webp', 'Немолодой неудачник радикально меняет жизнь, влюбившись в подругу дочери. Драма Сэма Мендеса, 5 «Оскаров»', 'Лестер Бернэм переживает кризис среднего возраста. Его не уважают и не ценят на работе, а от счастливой семьи осталась лишь видимость. У жены Кэролайн страстный роман с коллегой по работе, а угрюмая дочь-подросток Джейн увлечена соседским парнем, побывавшим в психиатрической больнице.

Терзаемый душевными муками Лестер впадает в депрессию. Но неожиданно для себя влюбляется в одноклассницу дочери Анджелу, и эта страсть дает Лестеру мощный жизненный импульс. Он ощущает прилив сил и желаний и готов снова радоваться красоте.', '18+', 300000000, 600000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', '...присмотрись', 122, '1999-06-01'),
  ('ebeae5e5-606a-4202-8477-4504dd853ead', 'Головокружение', 'Vertigo', 'films/pic128.webp', 'posters/pic128.webp', 'Детектив следит за блондинкой. Классический триллер Альфреда Хичкока о фобиях, сексе и помутнениях рассудка', 'Скотти Фергюсон — одинокий отставной сыщик, который страдает от патологического страха высоты. Давний друг по колледжу Гэвин Элстер просит его последить за своей женой Мэделин, одержимой идеей самоубийства.', '12+', 20000000, 60000000, 1958, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Можно ли вернуться из мира мертвых?', 128, '1958-06-01'),
  ('d80f2b5f-92aa-4eba-bb12-fed0d5df4394', 'Сансет бульвар', 'Sunset Blvd.', 'films/pic129.webp', 'posters/pic129.webp', 'Судьба сводит горе-сценариста и кинодиву, потерявшую связь с реальностью. Эталонный нуар, взявший три «Оскара»', 'Молодой сценарист Джо Гиллис сидит на мели, его преследуют кредиторы, ему не на что поесть, ему кажется, что жизнь кончилась. Машина, на которой он отправляется бездумно и бесцельно неизвестно куда, вдруг из-за лопнувшей шины резко виляет и влетает во двор особняка знаменитой в прошлом и увядающей в настоящем кинозвезды Нормы Десмонд.', '16+', 10000000, 10000000, 1950, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'A HOLLYWOOD STORY: Sensational...Daring...Unforgettable...Sunset Blvd', 110, '1950-06-01'),
  ('5d9ea8a8-1b48-4669-85ff-96071f380dc6', 'Апокалипсис сегодня', 'Apocalypse Now', 'films/pic130.webp', 'posters/pic130.webp', 'Запах напалма, «Полет валькирий» и зловещий полковник Курц. Один из важнейших фильмов в истории', 'Во время Вьетнамской войны капитан Уиллард отправляется вверх по реке в Камбоджу со спецзаданием: найти и убить сумасшедшего полковника Курца, создавшего в отдалённом районе нечто вроде собственного культа. По пути капитан становится свидетелем безумия и ужасов войны.', '18+', 10000000, 20000000, 1979, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The Horror… The Horror…', 194, '1979-06-01'),
  ('9e81d2be-094f-4c38-b23e-9e693421019e', 'Пианист', 'The Pianist', 'films/pic131.webp', 'posters/pic131.webp', 'Ужасы Холокоста глазами музыканта. Выдающаяся роль Эдриана Броуди и «Золотая пальмовая ветвь» в Каннах', 'Фильм снят по автобиографии Владислава Шпильмана, одного из лучших пианистов Польши 30-х годов прошлого века. Главный герой фильма — Владек — занимается искусством до тех пор, пока территорию Польши не занимают нацисты. Жизнь всех евреев меняется: их помещают в Варшавское гетто, запрещают работать, унижают, заставляют носить отличительные повязки, а через некоторое время отправляют в концлагерь.', '18+', 300000000, 300000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Music was his passion. Survival was his masterpiece', 149, '2002-06-01'),
  ('862892a3-752b-4062-a7fd-f32aa703cd0b', 'В джазе только девушки', 'Some Like It Hot', 'films/pic132.webp', 'posters/pic132.webp', 'Скрываясь от гангстеров, два музыканта выдают себя за девушек. Искрометная классика с Мэрилин Монро', 'Когда чикагские музыканты Джо и Джерри случайно становятся свидетелями бандитской перестрелки, они решают уехать на поезде во Флориду вместе с женским ансамблем. Сперва их план срабатывает, но вскоре любвеобильная солистка влюбляется в Джо.', '12+', 20000000, 160000000, 1959, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'cdf278db-e4f7-b2cf-f7f0-0f0afe4dc0f2', 'Marilyn Monroe and her bosom companions', 119, '1959-06-01'),
  ('96678bbe-3258-4dbd-ba00-b1de34695a1a', 'Убить пересмешника', 'To Kill a Mockingbird', 'films/pic133.webp', 'posters/pic133.webp', 'Отец-одиночка защищает в суде ложно обвиненного в изнасиловании афроамериканца. Оскароносная роль Грегори Пека', 'Юрист из Алабамы в одиночку воспитывает двоих детей. В обстановке экономической депрессии, преисполненной фанатизма и ненависти он должен защищать в суде афроамериканца, ложно обвиненного в изнасиловании.', '18+', 150000000, 450000000, 1962, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The most beloved and widely read Pulitzer Prize Winner now comes vividly alive on the screen!', 129, '1962-06-01'),
  ('0756ceb4-56a3-4c8f-8377-26809426ce04', 'Таксист', 'Taxi Driver', 'films/pic134.webp', 'posters/pic134.webp', 'Ветеран войны вязнет в пучине одиночества. Абсолютный шедевр Мартина Скорсезе с незабываемым Робертом Де Ниро', 'Тусклый свет слепых фонарей, скелеты фабричных труб, задыхающихся в собственном дыму. Вавилонские башни небоскребов, все это — ад Нового времени, Нью-Йорк.

Ветеран вьетнамской войны Трэвис Бикл ведет свое одинокое такси по ночным улицам бесконечного города, и перед ним разворачивается мрачная панорама человеческих грехов. Как ветхозаветный пророк, он надеется, что однажды небеса пошлют на землю спасительный дождь, который очистит Нью-Йорк от вековой грязи.

А когда умирает надежда, остается только ненависть. Огненный ливень обрушится на головы грешников. Таксист позаботится об этом.', '18+', 200000000, 600000000, 1976, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Он – одинокий, забытый человек, отчаянно пытающийся доказать что он - ВЫЖИВЕТ', 114, '1976-06-01'),
  ('d8d86d9c-1851-4423-8883-fd7fadab3aa3', 'Третий человек', 'The Third Man', 'films/pic135.webp', 'posters/pic135.webp', 'Автор детективов расследует гибель друга в Вене 1940-х. Шедевр нуара с «Оскаром» за операторскую работу', 'Холли Мартинс, автор бульварных романов, в надежде получить работу приезжает в послевоенную Вену по приглашению старинного приятеля Гарри Лайма. Увы, буквально накануне тот погиб в результате несчастного случая.

По мнению полицейского Кэллоуэя, Лайм был темной личностью, рэкетиром и спекулянтом. Мартинс решает провести собственное расследование, чтобы снять с друга обвинения в преступлениях, которые, как он уверен, тот не совершал.

Более того, Мартинс уверен, что его друг был убит, а его убийца где-то рядом...', '12+', 20000000, 60000000, 1949, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a18', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'HUNTED...By a thousand men! Haunted...By a lovely girl!', 104, '1949-06-01'),
  ('9af1b602-9755-4def-9402-61424eba1a41', 'Тропы славы', 'Paths of Glory', 'films/pic136.webp', 'posters/pic136.webp', '1916 год, Западный фронт. Полковник Дэкс командует пехотным полком французской армии. Уже два года союзники пытаются переломить ход войны. Начальник корпуса генерал Брулард приказывает дивизионному генералу Миро атаковать неприступную вражескую позицию.', '1916 год, Западный фронт. Полковник Дэкс командует пехотным полком французской армии. Уже два года союзники пытаются переломить ход войны. Начальник корпуса генерал Брулард приказывает дивизионному генералу Миро атаковать неприступную вражескую позицию.', '12+', 1000000, 3000000, 1957, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Never has the screen thrust so deeply into the guts of war!', 88, '1957-06-01'),
  ('4dafb437-5dc0-4e98-bfcd-c642457a7547', 'Бойцовский клуб', 'Fight Club', 'films/pic137.webp', 'posters/pic137.webp', 'Бессонница, драки и мыло. Контркультурный шедевр Дэвида Финчера, который можно пересматривать бесконечно', 'Сотрудник страховой компании страдает хронической бессонницей и отчаянно пытается вырваться из мучительно скучной жизни. Однажды в очередной командировке он встречает некоего Тайлера Дёрдена — харизматического торговца мылом с извращенной философией. Тайлер уверен, что самосовершенствование — удел слабых, а единственное, ради чего стоит жить, — саморазрушение.

Проходит немного времени, и вот уже новые друзья лупят друг друга почем зря на стоянке перед баром, и очищающий мордобой доставляет им высшее блаженство. Приобщая других мужчин к простым радостям физической жестокости, они основывают тайный Бойцовский клуб, который начинает пользоваться невероятной популярностью.', '18+', 1000000, 5000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Интриги. Хаос. Мыло', 139, '1999-06-01'),
  ('73ef5a2a-fdc1-4a1b-a02d-3ae6dc336469', 'Подводная лодка', 'Das Boot', 'films/pic138.webp', 'posters/pic138.webp', 'Осень 1941 года. Немецкая подводная лодка отправляется в Атлантический океан - место противостояния германского и британского флотов. Жизнь по строгому распорядку, учебные тревоги, воспоминания о семьях и любимых девушках, солёные мужские шуточки. Скоро всё это закончится. Потому что впереди – ад и никакой надежды на спасение.', 'Осень 1941 года. Немецкая подводная лодка отправляется в Атлантический океан - место противостояния германского и британского флотов. Жизнь по строгому распорядку, учебные тревоги, воспоминания о семьях и любимых девушках, солёные мужские шуточки. Скоро всё это закончится. Потому что впереди – ад и никакой надежды на спасение.', '16+', 200000000, 200000000, 1981, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Другая сторона Второй мировой войны', 150, '1981-06-01'),
  ('b7c190f5-ddad-45a0-9a22-95d27d2d277a', 'Секреты Лос-Анджелеса', 'L.A. Confidential', 'films/pic139.webp', 'posters/pic139.webp', 'Полицейские расследуют массовое убийство. Неонуар о темной стороне гламура 1950-х по роману Джеймса Эллроя', 'Бад Уайт и Эд Эксли работают в полиции Лос-Анджелеса. Они настолько разные, что порой ненавидят друг друга. Но их объединяет общее дело — расследование массового убийства. Оба пришли в полицию, чтобы бороться со злом, и оба — по личным причинам.', '18+', 200000000, 2000000000, 1997, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Off the record, on the QT, and very hush-hush...', 138, '1997-06-01'),
  ('8ee24394-c5df-49be-a8be-7b73f4a85f70', 'Двойная страховка', 'Double Indemnity', 'films/pic140.webp', 'posters/pic140.webp', 'Сластолюбивый страховой агент Уолтер Нефф отправляется продлить полис на машину некоему мистеру Дитрихсону. В его доме он встречается с миссис Дитрихсон и мгновенно воспламеняется. Красотка делает Уолтеру предложение, от которого он не может отказаться.', 'Сластолюбивый страховой агент Уолтер Нефф отправляется продлить полис на машину некоему мистеру Дитрихсону. В его доме он встречается с миссис Дитрихсон и мгновенно воспламеняется. Красотка делает Уолтеру предложение, от которого он не может отказаться.', '12+', 20000000, 40000000, 1944, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'IT''S LOVE AND MURDER AT FIRST SIGHT! (print ad - Lubbock Morning Avalanche - Lindsey Theatre - Lubbock, Texas - September 1, 1944 - all caps)', 107, '1944-06-01'),
  ('034e4d3e-8de6-4627-a3c1-0cc787a8f5f0', 'Китайский квартал', 'Chinatown', 'films/pic141.webp', 'posters/pic141.webp', 'Частный детектив Гиттес принимает предложение загадочной богатой красавицы заняться расследованием обстоятельств тайного романа ее мужа-инженера. Взявшись за дело, детектив оказывается в центре скандалов, беспредела коррупции и скрытых махинаций, правда о которых всплывет однажды ночью вместе с телом несчастного инженера.', 'Частный детектив Гиттес принимает предложение загадочной богатой красавицы заняться расследованием обстоятельств тайного романа ее мужа-инженера. Взявшись за дело, детектив оказывается в центре скандалов, беспредела коррупции и скрытых махинаций, правда о которых всплывет однажды ночью вместе с телом несчастного инженера.', '16+', 5000000, 5000000, 1974, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'You get tough. You get tender. You get close to each other. Maybe you even get close to the truth.', 130, '1974-06-01'),
  ('0802cf0c-5f34-4477-a3bb-33215f7e279f', 'Мальтийский сокол', 'The Maltese Falcon', 'films/pic142.webp', 'posters/pic142.webp', 'Сыщик ищет редкую статуэтку — а находит заговор. Самый влиятельный фильм-нуар в истории', 'Частный детектив Сэм Спэйд начинает смертельную охоту за таинственно исчезнувшей бесценной статуэткой «мальтийского сокола».', '12+', 200000000, 1000000000, 1941, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'He''s a Killer When He Hates!', 100, '1941-06-01'),
  ('9af26e8a-3362-4e48-b97b-c738abfd0c03', 'Реквием по мечте', 'Requiem for a Dream', 'films/pic143.webp', 'posters/pic143.webp', 'Жизнь героев катится под откос из-за наркозависимости. Безжалостная драма Даррена Аронофски', 'Каждый стремится к своей заветной мечте. Сара Голдфарб мечтала сняться в известном телешоу, ее сын Гарольд с другом Тайроном — сказочно разбогатеть, подруга Гарольда Мэрион грезила о собственном модном магазине, но на их пути были всевозможные препятствия. Все они выбирают неочевидные пути достижения своих целей, и мечты по-прежнему остаются недостижимыми, а жизни героев рушатся безвозвратно.', '18+', 1000000, 8000000, 2000, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Невыносимая легкость апокалипсиса', 102, '2000-06-01'),
  ('08c0957f-a26b-4676-a7ac-0842e4a5a590', 'Поющие под дождем', 'Singin'' in the Rain', 'films/pic144.webp', 'posters/pic144.webp', 'Актеру старой школы и начинающей артистке открывается мир звукового кино. Культовый мюзикл с Джином Келли', 'Основа этого легендарного фильма – дюжина старых песен, написанных для различных бродвейских шоу. Дон Локвуд – популярная звезда немого кино вспоминает о том, как он пришел к славе… но вдруг счастье покидает его – наступила эра звукового кино. Нужно осваивать новые горизонты.', '12+', 150000000, 750000000, 1951, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'MGM''s Musical Treasure !', 103, '1951-06-01'),
  ('49673881-6a2f-4c45-8b48-32eb4a497d0f', 'Мост через реку Квай', 'The Bridge on the River Kwai', 'films/pic145.webp', 'posters/pic145.webp', 'Захваченные в плен японцами британские солдаты и их командир полковник Николсон вынуждены строить железнодорожный мост через реку Квай в Бирме. Несмотря на свирепый характер полковника Сайто, Николсон проявляет настоящее мужество.

Тем временем командование назначает группу коммандос для уничтожения этого стратегически важного объекта.', 'Захваченные в плен японцами британские солдаты и их командир полковник Николсон вынуждены строить железнодорожный мост через реку Квай в Бирме. Несмотря на свирепый характер полковника Сайто, Николсон проявляет настоящее мужество.

Тем временем командование назначает группу коммандос для уничтожения этого стратегически важного объекта.', '16+', 50000000, 150000000, 1957, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a18', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'It spans a whole new world of entertainment!', 155, '1957-06-01'),
  ('85994f1e-3a4c-4650-ad6a-30dbad0a882f', 'Унесённые призраками', 'Sen to Chihiro no kamikakushi', 'films/pic146.webp', 'posters/pic146.webp', 'Девочка должна спасти своих родителей в мире духов. Шедевр Хаяо Миядзаки, фаворит анимационных рейтингов мира', 'Тихиро с мамой и папой переезжает в новый дом. Заблудившись по дороге, они оказываются в странном пустынном городе, где их ждет великолепный пир. Родители с жадностью набрасываются на еду и к ужасу девочки превращаются в свиней, став пленниками злой колдуньи Юбабы. Теперь, оказавшись одна среди волшебных существ и загадочных видений, Тихиро должна придумать, как избавить своих родителей от чар коварной старухи.', '12+', 300000000, 1500000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a15', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'The tunnel led Chihiro to a mysterious town...', 124, '2001-06-01'),
  ('1065a634-aea4-49e2-8cb9-aae95a5d5a9d', 'Спасти рядового Райана', 'Saving Private Ryan', 'films/pic147.webp', 'posters/pic147.webp', 'Отряд ищет солдата, чьи братья были убиты в бою. Драма Стивена Спилберга, вдохновленная реальной историей', 'Вторая мировая. Капитан Джон Миллер получает тяжелое задание. Вместе с отрядом из восьми человек он должен отправиться в тыл врага на поиски рядового Джеймса Райана, три родных брата которого почти одновременно погибли на полях сражений.

Командование приняло решение демобилизовать Райана и отправить его на родину к безутешной матери. Но чтобы найти и спасти солдата, крошечному отряду придется пройти через все круги ада.', '18+', 300000000, 2400000000, 1998, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '3c8df0a2-5d9e-4936-b8f7-8b91f5439f33', 'The movie that inspired to the world to remember', 169, '1998-06-01'),
  ('13efd782-5770-4d31-8fcf-1c8b8ea868c9', 'Всё о Еве', 'All About Eve', 'films/pic148.webp', 'posters/pic148.webp', 'Молодая интриганка вытесняет со сцены стареющую звезду. Шедевр Голливуда 1950-х, получивший шесть «Оскаров»', 'Стареющая звезда Бродвея Марго Ченнинг имела все: успех, друзей, молодого любовника. Скромная и трудолюбивая Ева становится ее помощницей, выполняющей все желания хозяйки. Быстрее всех понимает, что Евой движет желание стать «новой Марго Ченнинг», циничный театральный критик Аддисон Де Витт.
Пресыщенный жизнью и презирающий окружающую его благопристойность, он решает помочь молодой карьеристке. Она становится его благодарной ученицей и упорно, не гнушаясь ничем, идет к вершинам славы, предавая окружающих ее людей...', '12+', 50000000, 25000000, 1950, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'It''s all about women---and their men!', 138, '1950-06-01'),
  ('e35f67e8-f9b7-43ec-b323-5b9542434449', 'М убийца', 'M - Eine Stadt sucht einen Mörder', 'films/pic149.webp', 'posters/pic149.webp', 'Город объявляет охоту на детоубийцу. Классический триллер Фрица Ланга по мотивам страшной реальной истории', 'Маньяк наводит ужас на жителей Города. Маленькие девочки не успевают домой к обеду и не возвращаются вовсе. Полиция сбилась с ног в поисках преступника, однако все усилия тщетны. Обеспокоенный активностью полицейских преступный мир Города сам объявляет охоту на маньяка.', '18+', 10000000, 10000000, 1931, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a14', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'IT STAGGERS THE SENSES!...SHOCKS the Imagination - It will leave you Gasping - It is the Sensation of 3 Continents!', 108, '1931-06-01'),
  ('d564e341-bc2d-4ce7-b3f8-8fe13471bd8a', 'Бешеный бык', 'Raging Bull', 'films/pic150.webp', 'posters/pic150.webp', 'Джейк ЛаМотта, получивший прозвище Бронксский Бык, - боксер. И все его психологические и сексуальные комплексы яростно извергаются на боксерском ринге. Под горячую руку ему попадается родной брат, ставший жертвой навязчивой паранойи и ревности Джейка, а также пятнадцатилетняя девочка, которой суждено было стать самой главной наградой Джейка... и преследующим его наваждением.', 'Джейк ЛаМотта, получивший прозвище Бронксский Бык, - боксер. И все его психологические и сексуальные комплексы яростно извергаются на боксерском ринге. Под горячую руку ему попадается родной брат, ставший жертвой навязчивой паранойи и ревности Джейка, а также пятнадцатилетняя девочка, которой суждено было стать самой главной наградой Джейка... и преследующим его наваждением.', '16+', 200000000, 400000000, 1980, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', NULL, 129, '1980-06-01'),
  ('d393af15-24d7-4660-8b7c-da9356722482', 'Монти Пайтон и Священный Грааль', 'Monty Python and the Holy Grail', 'films/pic151.webp', 'posters/pic151.webp', 'Король Артур и рыцари Круглого стола отправляются в невероятное путешествие на поиски Святого Грааля. В пути они попадают в самые нелепые и абсурдные ситуации.', 'Король Артур и рыцари Круглого стола отправляются в невероятное путешествие на поиски Святого Грааля. В пути они попадают в самые нелепые и абсурдные ситуации.', '12+', 10000000, 10000000, 1975, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a18', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'And now! At Last! Another film completely different from some of the other films which aren''t quite the same as this one is', 91, '1975-06-01'),
  ('ddbb31df-ae7a-4240-95ca-f5873e232da3', 'Однажды на Диком Западе', 'C''era una volta il West', 'films/pic152.webp', 'posters/pic152.webp', 'Загадочный странник помогает вдове отстоять ранчо. Чарльз Бронсон в культовом спагетти-вестерне Серджио Леоне', 'Дикий Запад. Молодая вдова отказывается продать землю дельцу, задумавшему проложить по этой земле железную дорогу. Тогда бизнесмен поручает своему верному стрелку Фрэнку «устранить проблему», ведь тот ранее уже убил её мужа и приёмных детей. На защиту женщины встают известный бандит Шайен и таинственный незнакомец с губной гармошкой, у которого к Фрэнку давние счёты.', '18+', 50000000, 500000000, 1968, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'There were three men in her life. One to take her... one to love her... and one to kill her', 165, '1968-06-01'),
  ('51adeaf1-2811-4e29-b338-13c9d7f0a5c4', 'Семь', 'Se7en', 'films/pic153.webp', 'posters/pic153.webp', 'Детективы ищут маньяка, убивающего грешников. Выдающийся триллер Дэвида Финчера, ставший классикой жанра', 'Детектив Уильям Сомерсет — ветеран уголовного розыска, мечтающий уйти на пенсию и уехать подальше от города и его грешных обитателей. За семь дней до пенсии на Сомерсета сваливаются две неприятности: молодой напарник Миллс и особо изощренное убийство. Острый ум опытного следователя сразу определяет, что за этим преступлением, скорее всего, последуют другие.', '18+', 5000000, 5000000, 1995, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Он возомнил себя Богом и начал карать...', 127, '1995-06-01'),
  ('2c436103-c1e6-493e-aec3-27cd107f1f62', 'Крадущийся тигр, затаившийся дракон', 'Wo hu cang long', 'films/pic154.webp', 'posters/pic154.webp', 'В Китае XVIII века идет охота за чудесным мечом. Шедевр Энга Ли с изумительной смесью искусства и экшена', 'Легендарный мастер боевых искусств Ли Мубай отправляется на поиски магического меча зеленой стали, похищенного злоумышленниками. Впереди его ждет зловещая фигура давнего противника, наемного убийцы, который после долгого отсутствия снова вернулся на тропу войны.', '12+', 100000000, 800000000, 2000, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'A film by Ang Lee', 120, '2000-06-01'),
  ('518ba608-10eb-43a8-a754-6cfce90dc45e', 'Волшебник страны Оз', 'The Wizard of Oz', 'films/pic155.webp', 'posters/pic155.webp', 'Смерч уносит сироту в мир, полный чудес и приключений. Джуди Гарлэнд в киносказке, удостоенной двух «Оскаров»', 'Усаживайтесь поудобнее и приготовьтесь отправиться в долгое путешествие. Поднявшись выше радуги, вы окажетесь на дороге из желтого кирпича. Дорога проведет вас через заколдованные леса, царства злых ведьм и добрых фей в Изумрудный Город в далекой стране Оз. В мир, где любая мечта становится реальностью.', '0+', 20000000, 20000000, 1939, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'What is Oz?', 101, '1939-06-01'),
  ('91124848-6734-4f5c-bc92-45815aafa389', '2001 год: Космическая одиссея', '2001: A Space Odyssey', 'films/pic156.webp', 'posters/pic156.webp', 'Человек, компьютер и внеземной разум ведут опасный диалог. Грандиозная космическая притча Стэнли Кубрика', 'Экипаж космического корабля «Дискавери» — капитаны Дэйв Боумэн, Фрэнк Пул и их бортовой компьютер HAL 9000 — должны исследовать район галактики и понять, почему инопланетяне следят за Землей. На этом пути их ждет множество неожиданных открытий.', '12+', 5000000, 40000000, 1968, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'the time is now.', 149, '1968-06-01'),
  ('b240d55a-62dd-4acf-b8d1-297811e79270', 'Жизнь прекрасна', 'La vita è bella', 'films/pic157.webp', 'posters/pic157.webp', 'Отец изобретает игру, чтобы помочь сыну выжить в концлагере. Пронзительная история о силе духа и любви', 'Во время Второй мировой войны из Италии в концлагерь были отправлены евреи - отец с маленьким сыном. Жена-итальянка добровольно последовала за ними. В лагере отец сказал мальчику, что всё происходящее вокруг является большой интересной игрой за приз в виде настоящего танка. И этот классный приз достанется тому мальчику, который сможет не попасться на глаза надзирателям.', '16+', 100000000, 200000000, 1997, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'An unforgettable fable that proves love, family and imagination conquer all. (Canadian one sheet)', 116, '1997-06-01'),
  ('0ba455b2-56a1-42b3-b870-5b7e454d4799', 'Американская история X', 'American History X', 'films/pic158.webp', 'posters/pic158.webp', 'Экс-нацист пытается вытащить брата из группировки скинхедов. Знаковая антирасистская драма с Эдвардом Нортоном', 'Лидер местной банды скинхедов Дерек Виньярд прочно удерживает авторитет в своём районе. Убеждённый в своей правоте, он беспощадно расправляется с теми, кто имеет не белый цвет кожи. Независимость и смелость Дерека вызывают восхищение у его младшего брата Дэнни, который уже тоже сделал свой выбор.
Но совершённое Дереком зверское убийство двух чернокожих парней разделяет дороги братьев: Дерек оказывается в тюрьме, где существует свой расклад сил, а Дэнни на свободе успешно продолжает дело брата. До тех пор, пока их пути не пересекаются вновь.', '18+', 200000000, 400000000, 1998, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Преступление и наказание', 119, '1998-06-01'),
  ('f9fcd683-d828-4e28-80c5-f54fab00a738', 'Афера', 'The Sting', 'films/pic159.webp', 'posters/pic159.webp', 'У гениальных мошенников созрел грандиозный план. Дуэт Пола Ньюмана и Роберта Редфорда, семь премий «Оскар»', 'В 1930-е годы двое отпетых мошенников пытаются отомстить главарю мафии за смерть их общего друга с помощью одной из самых неожиданных афер в истории кино, которая к тому же заканчивается удивительным и забавным образом.', '6+', 150000000, 1500000000, 1973, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', '...all it takes is a little Confidence', 129, '1973-06-01'),
  ('fdb770bd-c82b-4eb0-b45a-057c804a0183', 'Печать зла', 'Touch of Evil', 'films/pic160.webp', 'posters/pic160.webp', 'В небольшом городке на границе с Мексикой творятся криминальные дела.', 'В небольшом городке на границе с Мексикой творятся криминальные дела.', NULL, 200000000, 1600000000, 1958, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The Overwhelming Drama of a Strange Vengeance', 95, '1958-06-01'),
  ('d28dbfe6-22d0-4de5-8521-80f5696bbc84', 'Маньчжурский кандидат', 'The Manchurian Candidate', 'films/pic161.webp', 'posters/pic161.webp', 'Корейская война, 1952 год. Отряд американских солдат попадает в ловушку и оказывается в секретной лаборатории врага, где над ними проводят эксперимент по «промывке мозгов». Штаб-сержанта Рэймонда Шоу, сына влиятельной супруги сенатора, превращают в запрограммированного убийцу, способного по специальной команде команде выполнить любой приказ. Внушив ему и остальным бойцам ложные воспоминания, их отправляют на родину, где Шоу награждают Медалью Почёта за якобы проявленный героизм и спасение отр...', 'Корейская война, 1952 год. Отряд американских солдат попадает в ловушку и оказывается в секретной лаборатории врага, где над ними проводят эксперимент по «промывке мозгов». Штаб-сержанта Рэймонда Шоу, сына влиятельной супруги сенатора, превращают в запрограммированного убийцу, способного по специальной команде команде выполнить любой приказ. Внушив ему и остальным бойцам ложные воспоминания, их отправляют на родину, где Шоу награждают Медалью Почёта за якобы проявленный героизм и спасение отряда. Однако после возвращения капитану Беннету Марко и другим спасённым солдатам начинают сниться кошмары, связанные с Рэймондом Шоу.', '12+', 10000000, 30000000, 1962, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'When you''ve seen it all, you''ll swear there''s never been anything like it!', 126, '1962-06-01'),
  ('ddf9ec5e-9ab2-4a95-8211-0ae0de06db77', 'Чужой', 'Alien', 'films/pic162.webp', 'posters/pic162.webp', 'Группа космонавтов высаживается на неизвестной планете и знакомится с ксеноморфом. Шедевр Ридли Скотта', 'В далеком будущем возвращающийся на Землю грузовой космический корабль перехватывает исходящий с неизвестной планеты сигнал. Экипаж, в соответствии с основными инструкциями, обязан найти и исследовать источник сигнала. Оказавшись на планете, астронавты повсюду обнаруживают предметы, по виду напоминающие гигантские коконы.', '18+', 150000000, 750000000, 1979, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'В космосе твой крик никто не услышит...', 116, '1979-06-01'),
  ('c33c2c3f-078b-4045-a771-57acf6844acc', 'Мистер Смит едет в Вашингтон', 'Mr. Smith Goes to Washington', 'films/pic163.webp', 'posters/pic163.webp', 'Молодой идеалист попадает в мир политических интриг. Джеймс Стюарт в драмеди с «Оскаром» за лучший сюжет', 'Наивный идеалист Джефферсон Смит, лидер организации бойскаутов, назначен представителем в сенат. Он объединяется со старшим сенатором от своего штата, однако не подозревает, как много людей вокруг него ведут двойную игру и выполняют приказания вышестоящих. Наивный молодой сенатор сталкивается с коррупцией, грязной игрой, лживостью и ангажированностью прессы.', '12+', 5000000, 40000000, 1939, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'OUR OPERATOR SAYS.."IT''S GOING TO BE A PLEASURE TO RUN "MR. SMITH GOES TO WASHINGTON" 5 DAYS STARTING SUNDAY, NOV.7) (print ad - Lubbock Morning Avalanche - Cactus Theatre - Lubbock Texas - November ', 129, '1939-06-01'),
  ('6cf410df-54ba-4165-a4c6-1852ee663843', 'Расёмон', 'Rashomon', 'films/pic164.webp', 'posters/pic164.webp', 'Одно преступление — четыре точки зрения. Абсолютный шедевр Акиры Куросавы', 'Древняя Япония. В лесу изнасилована женщина, а её муж убит. Есть четыре точки зрения на это происшествие, у каждого из четырех свидетелей — своя. Каждая сторона проливает свет на случившееся, добавляя дополнительные детали.', '18+', 20000000, 20000000, 1950, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a15', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The husband, the wife...or the bandit?', 88, '1950-06-01'),
  ('f47b5da4-889d-4714-90e6-a9aa826f9b55', 'Леон', 'Léon', 'films/pic165.webp', 'posters/pic165.webp', 'Осиротевшая девочка становится напарницей наемного убийцы. Культовый триллер с Жаном Рено и Натали Портман', 'Профессиональный убийца Леон неожиданно для себя самого решает помочь 12-летней соседке Матильде, семью которой убили коррумпированные полицейские.', '18+', 20000000, 60000000, 1994, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Вы не можете остановить того, кого не видно', 133, '1994-06-01'),
  ('945a2af1-b946-4691-a61d-7d9c8d45e0c7', 'Энни Холл', 'Annie Hall', 'films/pic166.webp', 'posters/pic166.webp', 'Комик Элви Сингер с юмором и иронией рассказывает о своей жизни, о людях, которые его окружают. Он скептически анализирует свои неудачи в личной жизни, в которой было несколько любимых женщин.', 'Комик Элви Сингер с юмором и иронией рассказывает о своей жизни, о людях, которые его окружают. Он скептически анализирует свои неудачи в личной жизни, в которой было несколько любимых женщин.', '12+', 100000000, 500000000, 1977, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'A nervous romance', 93, '1977-06-01'),
  ('c5e80a22-1c52-42ce-abd3-216975127b9c', 'Заводной апельсин', 'A Clockwork Orange', 'films/pic167.webp', 'posters/pic167.webp', 'Власти пытаются перевоспитать подростка-психопата. Скандальная экранизация шедевра Энтони Бёрджесса', 'Безжалостный лидер банды подростков, совершающей убийства и изнасилования, попадает в тюрьму и подвергается специальной обработке по подавлению подсознательного стремления к насилию. Но жизнь за воротами тюрьмы такова, что меры, принятые по «исправлению жестокости характера», не могут ничего изменить.', '18+', 300000000, 600000000, 1971, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'cdf278db-e4f7-b2cf-f7f0-0f0afe4dc0f2', 'Being the adventures of a young man ... who couldn''t resist pretty girls ... or a bit of the old ultra-violence ... went to jail, was re-conditioned ... and came out a different young man ... or was ', 137, '1971-06-01'),
  ('c9634e51-7448-4870-b696-f2d4a210862b', 'Большой побег', 'The Great Escape', 'films/pic168.webp', 'posters/pic168.webp', 'Американские, британские и канадские военнопленные осуществляют массовый побег из немецкого лагеря во время Второй мировой войны.', 'Американские, британские и канадские военнопленные осуществляют массовый побег из немецкого лагеря во время Второй мировой войны.', '12+', 100000000, 50000000, 1963, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Hours ago... Minutes ago.... These men were behind barbed wire', 172, '1963-06-01'),
  ('91a412c1-9869-45a8-9fee-b5865f6b54f1', 'Сокровища Сьерра Мадре', 'The Treasure of the Sierra Madre', 'films/pic169.webp', 'posters/pic169.webp', 'В небольшом мексиканском городке Тампико знакомятся два бедняка Доббс и Кертин. От местного старика они узнают о золотой жиле в окрестностях Сьерра Мадре. Вложив все свои деньги в дело, трое друзей отправляются в опасное путешествие.

Дойти туда стоит огромных трудов, но сохранить трезвый разум при виде жёлтого металла и вернуться живым ещё сложнее.', 'В небольшом мексиканском городке Тампико знакомятся два бедняка Доббс и Кертин. От местного старика они узнают о золотой жиле в окрестностях Сьерра Мадре. Вложив все свои деньги в дело, трое друзей отправляются в опасное путешествие.

Дойти туда стоит огромных трудов, но сохранить трезвый разум при виде жёлтого металла и вернуться живым ещё сложнее.', '12+', 200000000, 400000000, 1947, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Warner Bros. hit a new high in high adventure... bringing another best-seller to the screen!', 126, '1947-06-01'),
  ('a6d38cb5-a200-4cd1-8e79-15163c88fb79', 'Бешеные псы', 'Reservoir Dogs', 'films/pic170.webp', 'posters/pic170.webp', 'Гангстеры артистично спорят о том, кто их кинул. Кровожадный и веселый дебют Квентина Тарантино', 'Это должно было стать идеальным преступлением. Задумав ограбить ювелирный магазин, криминальный босс Джо Кэбот собрал вместе шестерых опытных и совершенно незнакомых друг с другом преступников. Но с самого начала все пошло не так, и обычный грабеж превратился в кровавую бойню.', '18+', 300000000, 3000000000, 1991, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Let''s get the job done', 100, '1991-06-01'),
  ('4e140c45-b620-49da-97f0-3691d2288893', 'Шестое чувство', 'The Sixth Sense', 'films/pic171.webp', 'posters/pic171.webp', 'Детский психолог открывает жуткую тайну маленького пациента. Грандиозная мистическая драма с Брюсом Уиллисом', 'Детский психиатр Малкольм Кроу сталкивается со странным случаем: девятилетнего Коула посещают страшные видения — призраки умерших. Как врач Малкольм бессилен помочь, но как человек он пытается найти ключ к ужасному миру Коула.', '12+', 100000000, 1000000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Иногда дар – это проклятие', 107, '1999-06-01'),
  ('981fc1e3-8bac-4b01-ba03-80e1d6e6216f', 'Челюсти', 'Jaws', 'films/pic172.webp', 'posters/pic172.webp', 'Три храбреца борются с гигантской акулой-убийцей. Оскароносный шедевр Стивена Спилберга, напугавший весь мир', 'Небольшой курортный городок Эмити, расположенный на одноимённом острове, готовится к летнему наплыву туристов и празднованию Дня независимости. В один из дней начальник полиции Мартин Броуди и его помощник находят на берегу останки тела девушки, которая стала первой жертвой огромной белой акулы, которая появилась у берегов Эмити. Броуди пытается закрыть пляж, но сталкивается с противодействием мэра, который считает, что это повредит городу во время туристического сезона. Однако с каждым днём число жертв кровожадной акулы продолжает увеличиваться. Для обезвреживания хищника в опасную морскую экспедицию вместе с охотником на акул Куинтом отправляются сам Броуди и прибывший на остров эксперт-океанограф Мэтт Хупер.', '18+', 20000000, 100000000, 1975, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'You''ll never go in the water again!', 124, '1975-06-01'),
  ('774a2ebe-3754-4b78-9043-777a917b545d', 'Амадей', 'Amadeus', 'films/pic173.webp', 'posters/pic173.webp', 'Придворный композитор смертельно завидует молодому гению. Яркая драма Милоша Формана, получившая 8 «Оскаров»', 'Вена, 1823 год. Антонио Сальери, некогда уважаемый придворный композитор императора Иосифа II, доживает дни в сумасшедшем доме. В исповеди он вспоминает свою жизнь, ознаменованную противостоянием с молодым Вольфгангом Амадеем Моцартом, который словно играючи создавал музыку, подобную голосу небес. Сальери, разрываемый завистью и восхищением перед гением, поклялся Богу во что бы то ни стало уничтожить соперника.', '18+', 80000000, 640000000, 1984, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Мастер... Музыка... Безумие... Убийство... Киношедевр... ... Все, что вы слышали, - правда', 160, '1984-06-01'),
  ('8b1868fb-32dc-45b8-9cd6-8ee49604d1b9', 'В порту', 'On the Waterfront', 'films/pic174.webp', 'posters/pic174.webp', 'Бывший боксёр идёт против своего босса-мафиози. Классика американского кино, первый «Оскар» Марлона Брандо', 'В центре сюжета судьба простого докера - Терри Мэллоу, терзающегося сомнениями и решающего встать на путь восстановления справедливости, после того как выясняется, что он работает на настоящего гангстера - коррумпированного босса портовых докеров Джонни Фрэндли.', '16+', 1000000, 8000000, 1954, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'It walked away with just about every award there was - and it still could !', 108, '1954-06-01'),
  ('89f3f86b-6f21-4d1d-a767-c313a8919966', 'Храброе сердце', 'Braveheart', 'films/pic175.webp', 'posters/pic175.webp', 'История национального героя Шотландии Уильяма Уоллеса. Зрелищный эпос Мэла Гибсона, удостоенный 5 «Оскаров»', 'Действие фильма начинается в 1280 году в Шотландии. Это история легендарного национального героя Уильяма Уоллеса, посвятившего себя борьбе с англичанами при короле Эдварде Длинноногом.
Он рано лишился отца, погибшего от рук англичан, и его забрал к себе дядя Оргайл, который дал ему хорошее образование в Европе. На родину Уильям возвращается уже взрослым человеком, мечтающим завести семью и жить мирной жизнью.
Но судьба распорядилась иначе. Его невесту убили англичане, и он начал свой крестовый поход за свободу.', '18+', 10000000, 10000000, 1995, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Все умирают, но не все живут по-настоящему', 178, '1995-06-01')
ON CONFLICT (title, year) DO NOTHING;

