  ((SELECT id FROM actor WHERE russian_name = 'Софи Марсо' AND (original_name = 'Sophie Marceau' OR (original_name IS NULL AND 'Sophie Marceau' IS NULL))), (SELECT id FROM film WHERE title = 'Храброе сердце' AND year = 1995), 'Princess Isabelle', NULL),
  ((SELECT id FROM actor WHERE russian_name = 'Патрик МакГуэн' AND (original_name = 'Patrick McGoohan' OR (original_name IS NULL AND 'Patrick McGoohan' IS NULL))), (SELECT id FROM film WHERE title = 'Храброе сердце' AND year = 1995), 'Longshanks - King Edward I', NULL),
  ((SELECT id FROM actor WHERE russian_name = 'Энгус Макфадьен' AND (original_name = 'Angus Macfadyen' OR (original_name IS NULL AND 'Angus Macfadyen' IS NULL))), (SELECT id FROM film WHERE title = 'Храброе сердце' AND year = 1995), 'Robert the Bruce (в титрах: Angus McFadyen)', NULL),
