INSERT INTO film (id, title, original_title, cover, poster,
                 short_description, description, age_category,
                 budget, worldwide_fees, year, country_id, genre_id,
                 slogan, duration, release_date)
VALUES
  ('92ad300f-4c3c-42be-a86c-f25913728110', 'Ран', 'Ran', 'films/pic176.webp', 'posters/pic176.webp', 'Даймё делит между сыновьями наследство, но приводит их к войне. Трагедия Шекспира в переложении Акиры Куросавы', 'Япония, XVI век. Стареющий правитель Хидэтора объявляет о разделе своих владений между тремя сыновьями. Обманутый фальшивыми уверениями в верности двух старших сыновей Хидэтора прогоняет младшего, осмелившегося утверждать, что решение отца навлечет гибель на весь их род. Став жертвой коварного предательства, правитель лишается рассудка, а между его наследниками начинается беспощадная братоубийственная война.', '18+', 10000000, 20000000, 1985, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', NULL, 162, '1985-06-01'),
  ('3dd2fcdc-001d-4e00-8515-0d4637d6933b', 'Ровно в полдень', 'High Noon', 'films/pic177.webp', 'posters/pic177.webp', 'Шериф в одиночку противостоит банде безжалостных убийц. Оскароносный вестерн с Гэри Купером и Грейс Келли', 'Только что поженившись, Уилл и его прекрасная блондинка-квакерша Эми собираются навсегда покинуть городок, намереваясь оставить в прошлом опасную работу и обзавестись собственным ранчо, чтобы пустить корни. Однако, в городке узнают, что свирепый убийца Фрэнк Миллер должен очень скоро приехать в Хэдливиль и отомстить Уиллу и всему городу за то, что они засадили его в тюрьму несколько лет тому назад. Брат Миллера и еще два бандита-ганфайтера уже ждут поезд, на котором едет Миллер, а поезд должен прийти ровно в полдень. В минуту паники Уилл покидает город вместе с невестой и скачет по дороге в открытые прерии, но внезапно останавливает коня.', '12+', 50000000, 250000000, 1952, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Simple. Powerful. Unforgettable.', 85, '1952-06-01'),
  ('99dbc227-6733-42f3-a774-ca1a4bb15565', 'Фарго', 'Fargo', 'films/pic178.webp', 'posters/pic178.webp', 'Инсценировка похищения жены приводит к рекам крови. Шедевр братьев Коэн о человеческой жестокости и глупости', 'Для робкого менеджера по продажам, работающего у собственного тестя, похищение собственной жены — отличная идея. Он нанимает двух преступников, чтобы по результатам разделить с ними крупный выкуп за заложницу. Но дело сразу идет не так, как замышлялось, проливается кровь... Вызов преступникам бросает отважная женщина-полицейский...', '18+', 80000000, 160000000, 1995, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'An ordinary place, an extraordinary thriller', 98, '1995-06-01'),
  ('fae45038-e9db-41b6-8dc6-3100d5714923', 'Бегущий по лезвию', 'Blade Runner', 'films/pic179.webp', 'posters/pic179.webp', 'Детектив Декард преследует сбежавших андроидов. Культовый киберпанк Ридли Скотта о человеке и человечности', 'Ноябрь 2019 года. Бывший охотник на андроидов Рик Декард восстановлен в полиции Лос-Анджелеса для поиска возглавляемой Роем Батти группы репликантов, совершившей побег из космической колонии на Землю. В полиции считают, что андроиды пытаются встретиться с Эндолом Тайреллом — руководителем корпорации, которая разрабатывает кибернетический интеллект. Декард получает задание выяснить мотивы репликантов и уничтожить их.', '18+', 10000000, 100000000, 1982, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'A Futuristic Vision Perfected', 117, '1982-06-01'),
  ('b9e41194-7650-4d8e-b1a6-d19372f4078a', 'Квартира', 'The Apartment', 'films/pic180.webp', 'posters/pic180.webp', 'Скромный служащий страховой компании Бакстер, чтобы хоть как-то продвинуться по карьерной лестнице, одалживает ключи от своей холостяцкой квартиры не только приятелям, желающим «погулять на сторону», но и боссу. Когда дела начинают идти в гору, случается непредвиденное: Бакстер влюбляется в любовницу босса.', 'Скромный служащий страховой компании Бакстер, чтобы хоть как-то продвинуться по карьерной лестнице, одалживает ключи от своей холостяцкой квартиры не только приятелям, желающим «погулять на сторону», но и боссу. Когда дела начинают идти в гору, случается непредвиденное: Бакстер влюбляется в любовницу босса.', '16+', 50000000, 400000000, 1960, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Movie-wise, there has never been anything like it - laugh-wise, love-wise, or otherwise-wise!', 125, '1960-06-01'),
  ('61a94557-4218-45d3-831f-511edd2f8fbe', 'История игрушек 2', 'Toy Story 2', 'films/pic181.webp', 'posters/pic181.webp', 'Ковбой Вуди в опасности! Только друзья могут его спасти. Продолжение, которое оказалось даже лучше оригинала', 'Ковбой Вуди и другие игрушки мальчика по имени Энди продолжают жить, радуясь каждому дню. Но неожиданно все меняется, когда Вуди похищает коварный коллекционер. Оказывается, что Вуди - очень ценная игрушка из коллекции, за которую японский музей игрушек готов заплатить огромную сумму. В доме коллекционера он находит своих родственников. В это время игрушки во главе с Баззом Лайтером отправляются спасать Вуди.
Вуди узнает о своем знаменитом прошлом, Базз и другие игрушки проходят опасный и тернистый путь. Перед Вуди встает непростой вопрос - каково же его предназначение? Блистать в витрине музея или же вернуться к любимому хозяину?', '0+', 100000000, 300000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'The Toys are Back in Town', 92, '1999-06-01'),
  ('73396409-f8b5-44ca-98b5-28e095540ee7', 'Чужие', 'Aliens', 'films/pic182.webp', 'posters/pic182.webp', 'Эллен Рипли снова в логове ксеноморфов. Вторая часть фантастической экшен-франшизы с «Оскаром» за спецэффекты', 'Чужой – совершенный организм. Идеальная машина для убийства, чье физическое превосходство сочетается с его феноменальной жаждой уничтожения. Офицер Элен Рипли и команда космического корабля Ностромо один раз уже встретилась с такой тварью. В живых осталась только Элен.

Капсула с Элен найдена спасателями после многих лет блуждания в космосе. Ей сообщают, что планета L.V. 426 колонизирована, и ей придется вернуться туда, где начался ее кошмар, ибо связь с колонистами прервалась. И вот в составе группы космического десанта Рипли отправляется на проклятую планету. Но теперь их там поджидает не один Чужой, а тысячи. Кто сможет выжить в этой войне: чудовища, способные только убивать, или люди, способные мыслить?', '18+', 50000000, 50000000, 1986, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'В некоторых местах Вселенной вы не одиноки...', 137, '1986-06-01'),
  ('cf094897-d2f5-4d57-ad68-9c29d1ab43c4', 'Незнакомцы в поезде', 'Strangers on a Train', 'films/pic183.webp', 'posters/pic183.webp', 'Случайные попутчики обсуждают взаимовыгодные убийства. Триллер-нуар — абсолютный шедевр Альфреда Хичкока', 'Невероятные события начинают происходить в жизни звезды тенниса Гая Хэйнса после неожиданной встречи в поезде с обаятельным незнакомцем Бруно.

До этой встречи молодые люди имели разные, но серьезные причины чувствовать себя несчастными. Решение личных проблем двух случайных попутчиков состоит из небольшого обмена услугами: «Я убью для тебя, а ты убьешь для меня».', '12+', 10000000, 100000000, 1951, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'It starts with a shriek of a train whistle...and ends with shrieking excitement', 101, '1951-06-01'),
  ('8e864c5f-0f92-4e46-b23c-650bd71c6aa9', 'Новые времена', 'Modern Times', 'films/pic184.webp', 'posters/pic184.webp', 'Маленький Бродяга ищет счастья в разгар Великой депрессии. Последний немой шедевр Чарльза Чаплина', '«Новые времена» - это эмоциональный, выдержанный в комическом ключе, отклик на перекосы машинной эпохи. Маленький Бродяга не желает быть «винтиком» в огромной мега-машине промышленного производства и так похожего на него человеческого общества. Чарли сражается с тупыми богачами, всесильными полицейскими, бездушными начальниками конвейерного производства.

Иногда он выигрывает в этих сражениях, но чаще проигрывает, в конце концов, бесстрашно идет навстречу рассвету. Хотя «Новые времена» считается последним немым фильмом Чарли Чаплина, в нем Маленький Бродяга в первый и в последний раз обрел голос.

Правда, он не заговорил, а запел в финальных кадрах картины, символизируя прощание с прекрасным периодом немого кинематографа.', '0+', 200000000, 400000000, 1936, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'He stands alone as the greatest entertainer of modern times! No one on earth can make you laugh as heartily or touch your heart as deeply...the whole world laughs, cries and thrills to his priceless g', 87, '1936-06-01'),
  ('e28b8651-5004-458c-853c-37e2d309e57d', 'Сияние', 'The Shining', 'films/pic185.webp', 'posters/pic185.webp', 'Писатель, запертый с семьей в заснеженном отеле, теряет рассудок. Культовый эстетский хоррор Стэнли Кубрика', 'Джек Торренс с женой и сыном приезжает в элегантный отдалённый отель, чтобы работать смотрителем во время мертвого сезона. Торренс здесь раньше никогда не бывал. Или это не совсем так? Ответ лежит во мраке, сотканном из преступного кошмара.', '18+', 80000000, 240000000, 1980, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The Horror is driving him crazy', 144, '1980-06-01'),
  ('e6db85a1-c4d5-4257-ace2-b13d865272cf', 'Донни Дарко', 'Donnie Darko', 'films/pic186.webp', 'posters/pic186.webp', 'Парень видит человека-кролика, который пророчит конец света. Культовый триллер, породивший уйму теорий', 'Донни Дарко — обычный старшеклассник, живет с родителями и двумя сестрами. Однажды он встречает человека в костюме кролика, который сообщает парню, что через 28 дней, 6 часов, 42 минуты и 12 секунд наступит конец света.', '18+', 150000000, 450000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Be Afraid of the Dark', 113, '2001-06-01'),
  ('5c1178f7-c67f-480f-b516-867159ede57d', 'Утиный суп', 'Duck Soup', 'films/pic187.webp', 'posters/pic187.webp', 'Чтобы спасти маленькую страну Фридонию от банкротства, богатая вдова госпожа Тисдейл соглашается пожертвовать на это 20 миллионов долларов. Но только при условии, что ухлестывающий за ней Руфус Т. Файрфлай станет лидером страны.

Файрфлай - циничный и бесцеремонный диктатор - провоцирует посла соседней Сильвании, и между странами начинается война. Военную «игру» осложняют и запутывают два друга-неумехи, которых посол Сильвании отправил шпионить за Файрфлаем с целью выкрасть его тайные планы с...', 'Чтобы спасти маленькую страну Фридонию от банкротства, богатая вдова госпожа Тисдейл соглашается пожертвовать на это 20 миллионов долларов. Но только при условии, что ухлестывающий за ней Руфус Т. Файрфлай станет лидером страны.

Файрфлай - циничный и бесцеремонный диктатор - провоцирует посла соседней Сильвании, и между странами начинается война. Военную «игру» осложняют и запутывают два друга-неумехи, которых посол Сильвании отправил шпионить за Файрфлаем с целью выкрасть его тайные планы сражения...', '0+', 20000000, 10000000, 1933, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'War Is Swell ...when the Marx Brothers are in it. They''ll be out of the trenches by Christmas...if the food doesn''t improve', 69, '1933-06-01'),
  ('85c06813-d0b6-4188-86ab-2971a36b4c0b', 'Принцесса-невеста', 'The Princess Bride', 'films/pic188.webp', 'posters/pic188.webp', 'За красавицей Лютик гоняются принц, трое бандитов и главарь пиратов. Изобретательная сказка с юной Робин Райт', 'Добро пожаловать в фантастический мир прекрасных замков, жутких подземелий, бескрайних океанов, лесов и гор. Чтобы спасти свою возлюбленную, прекрасную невесту, отважный герой преодолевает немыслимые препятствия и совершает невероятные подвиги.', '6+', 300000000, 600000000, 1987, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'The story of a man and a woman who lived happily ever after. Even though the courtship almost killed them.', 98, '1987-06-01'),
  ('00c97a67-d20c-4689-be5c-a10b98cb548d', 'Беги, Лола, беги', 'Lola rennt', 'films/pic189.webp', 'posters/pic189.webp', 'У нее есть 20 минут, чтобы спасти бойфренда от гибели. Сумасшедшие драйв и любовь в самом модном триллере 1990-х', 'Лола и Манни живут в Берлине и безумно любят друг друга. И когда Манни — маленький курьер большого бандита — теряет сумку с деньгами своего босса, спасти его может только Лола. Но чтобы раздобыть совсем не маленькую сумму в сто тысяч марок, у девушки есть только 20 минут. Каждая секунда может означать разницу между жизнью и смертью.', '18+', 200000000, 2000000000, 1998, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a14', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The difference between life or death can be decided in a split second', 81, '1998-06-01'),
  ('7c4f0568-0e8b-44e1-9924-5de776616b2e', 'Огни большого города', 'City Lights', 'films/pic190.webp', 'posters/pic190.webp', 'Влюбленный нищий ищет деньги на операцию для слепой красавицы. Лирическая комедия с Чарльзом Чаплином', 'Маленький Бродяга встречает красивую слепую девушку, торгующую цветами на улице, которая по ошибке принимает его за богатого герцога. Узнав о том, что операция может вернуть ей зрение, маленький Бродяга пускается на поиски денег.', '0+', 150000000, 300000000, 1931, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'HE RETURNS -And the world rocks again with laughter. (Print Ad-Daily Examiner, ((Grafton, NSW)) 6 July 1931)', 87, '1931-06-01'),
  ('c2ffc9b2-8f9b-47f3-a32d-e0503cb2a671', 'Паровоз Генерал', 'The General', 'films/pic191.webp', 'posters/pic191.webp', 'Отважный машинист возвращает угнанный поезд и завоевывает любовь девушки. Бастер Китон в шедевре немого кино', 'Юного Джонни Грэя в армию Конфедерации не взяли, а его возлюбленная Аннабел Ли отвергает его, обозвав трусом. Тем не менее, он со своим «напарником» паровозом утирает всем нос, выигрывая сражение. Джонни воюет с угонщиками поезда, непослушной пушкой и непредсказуемой силой судьбы.', '18+', 100000000, 200000000, 1926, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Buster drives "The General" to trainload of laughter. (Trade paper ad).', 80, '1926-06-01'),
  ('db27780a-47de-4735-bad2-edf28abf2f67', 'Искатели', 'The Searchers', 'films/pic192.webp', 'posters/pic192.webp', 'Бывший солдат армии конфедерации Итан Эдвардс ищет племянницу, похищенную команчами, которые убили всю его семью.', 'Бывший солдат армии конфедерации Итан Эдвардс ищет племянницу, похищенную команчами, которые убили всю его семью.', '6+', 5000000, 50000000, 1956, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The Biggest, Roughest, Toughest ...and Most Beautiful Picture Ever Made!', 119, '1956-06-01'),
  ('2192a82b-3c0d-423c-b49e-b45c6195f316', 'Метрополис', 'Metropolis', 'films/pic193.webp', 'posters/pic193.webp', 'Доведенные до отчаяния рабочие восстают против праздной элиты. Эпичная футуристическая антиутопия Фрица Ланга', 'Метрополис - город будущего, разделен на две части. Под землей находятся жилища рабочих, над ними цеха с машинами. В верхнем городе расположены офисы, богатые кварталы и сады развлечений. Вся власть в городе принадлежит магнату Иогану Фендерсону.
Его сын - Фредер догадывается о несправедливости, царящей в метрополисе. Спустившись в машинную зону, Фредер приходит в ужас: он видит страшного Молоха, пожирающего людей. Не в силах смириться с увиденным, он начинает борьбу со злом.', '12+', 5000000, 10000000, 1927, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a14', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'There can be no understanding between the hands and the brain unless the heart acts as mediator', 145, '1927-06-01'),
  ('d1b614c7-527a-4611-8c03-20c55cc9e2d3', 'Цельнометаллическая оболочка', 'Full Metal Jacket', 'films/pic194.webp', 'posters/pic194.webp', 'Новобранцев жестоко тренируют перед Вьетнамом, а потом они попадают в ад. Антивоенный шедевр Стэнли Кубрика', 'Американская база подготовки новобранцев корпуса морской пехоты. Жесточайшая, бесчеловечная система призвана превратить домашних мальчишек в натренированных хладнокровных убийц. Их готовят к войне во Вьетнаме, где им придется часто задавать себе вопрос «Разве война - это не ад?», а иначе просто невозможно убивать каждый день, не понимая, для чего это?', '18+', 80000000, 40000000, 1987, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Born to Kill', 116, '1987-06-01'),
  ('3486c5b3-fb7d-48a3-b20f-7cee241af06f', 'Дурная слава', 'Notorious', 'films/pic195.webp', 'posters/pic195.webp', '1946 г. американский суд приговаривает Иогана Губермана к двадцати годам тюрьмы как германского шпиона за измену Родине. Его дочь Алисия знакомится на вечеринке с агентом ФБР Дэвлином, который получает задание от руководства раскрыть нацистский заговор в Рио де Жанейро.

Дэвлин решает воспользоваться помощью девушки для выполнения своего задания, и она принимает его предложение. Так начинается их бурный «шпионский» роман.

Они вступают в контакт с нацистским агентом Александром, за которого А...', '1946 г. американский суд приговаривает Иогана Губермана к двадцати годам тюрьмы как германского шпиона за измену Родине. Его дочь Алисия знакомится на вечеринке с агентом ФБР Дэвлином, который получает задание от руководства раскрыть нацистский заговор в Рио де Жанейро.

Дэвлин решает воспользоваться помощью девушки для выполнения своего задания, и она принимает его предложение. Так начинается их бурный «шпионский» роман.

Они вступают в контакт с нацистским агентом Александром, за которого Алисия должна выйти замуж, чтобы узнать о секретных планах немецкой организации, в которой состоит Александр.', '12+', 300000000, 150000000, 1946, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The screen''s top romantic stars in a melodramatic masterpiece!', 102, '1946-06-01'),
  ('1f464e7a-b448-4d7f-a854-c1971210aa2f', 'Манхэттен', 'Manhattan', 'films/pic196.webp', 'posters/pic196.webp', 'Сценарист телешоу Айзек Дэвис пытается дописать книгу и после болезненного развода встречается с девушкой значительно моложе его. Он решает бросить опостылевшую работу на телевидении, а знакомство с любовницей женатого друга привносит в его и без того беспокойную жизнь ещё больше волнений.', 'Сценарист телешоу Айзек Дэвис пытается дописать книгу и после болезненного развода встречается с девушкой значительно моложе его. Он решает бросить опостылевшую работу на телевидении, а знакомство с любовницей женатого друга привносит в его и без того беспокойную жизнь ещё больше волнений.', '18+', 20000000, 200000000, 1979, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Woody Allen''s New Comedy Hit', 96, '1979-06-01'),
  ('ea514ea2-7786-4784-8f57-434ccb651bed', 'Буч Кэссиди и Сандэнс Кид', 'Butch Cassidy and the Sundance Kid', 'films/pic197.webp', 'posters/pic197.webp', 'Два друга Буч Кэссиди и Сандэнс Кид известны всей округе. Они верховодят бандой «Дыра в стене». Буч - мозговой центр, Сандэнс - идеальный исполнитель и первоклассный стрелок. Они дважды грабят один и тот же поезд, перевозящий деньги. 

За налетчиками организована погоня, которой руководит опытный следопыт Балтимор. От него не удавалось уйти никому. С трудом оторвавшись от преследования, приятели укрываются в доме подружки Сандэнса. И тогда Буч понимает: раз удача отвернулась от них в Америке,...', 'Два друга Буч Кэссиди и Сандэнс Кид известны всей округе. Они верховодят бандой «Дыра в стене». Буч - мозговой центр, Сандэнс - идеальный исполнитель и первоклассный стрелок. Они дважды грабят один и тот же поезд, перевозящий деньги. 

За налетчиками организована погоня, которой руководит опытный следопыт Балтимор. От него не удавалось уйти никому. С трудом оторвавшись от преследования, приятели укрываются в доме подружки Сандэнса. И тогда Буч понимает: раз удача отвернулась от них в Америке, может стоит попытать счастья в Боливии?', '12+', 80000000, 240000000, 1969, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'They''re taking trains... They''re taking banks and they''re taking one piece of baggage!', 110, '1969-06-01'),
  ('bd489eb1-d78f-408f-8765-64c6b83dcb54', 'Выпускник', 'The Graduate', 'films/pic198.webp', 'posters/pic198.webp', 'После окончания колледжа в родительский дом возвращается Бенджамин Брэддок. На торжественном приёме в его честь Бен встречает давнюю приятельницу родителей, элегантную даму миссис Робинсон, которая позже соблазняет его. Робкий, неуклюжий, безвольный Бен бессилен против чар властной и сексуальной женщины, пока не влюбляется в её дочь Элейн.', 'После окончания колледжа в родительский дом возвращается Бенджамин Брэддок. На торжественном приёме в его честь Бен встречает давнюю приятельницу родителей, элегантную даму миссис Робинсон, которая позже соблазняет его. Робкий, неуклюжий, безвольный Бен бессилен против чар властной и сексуальной женщины, пока не влюбляется в её дочь Элейн.', '16+', 20000000, 20000000, 1967, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'This is Benjamin. He''s a little worried about his future', 105, '1967-06-01'),
  ('c0ab6fd3-56b8-4262-99ca-2e293edba8f0', 'Глубокий сон', 'The Big Sleep', 'films/pic199.webp', 'posters/pic199.webp', 'Пожилой генерал Стернвуд нанимает частного детектива Филипа Марлоу, чтобы тот разобрался с шантажистами его распутной младшей дочери Кармен. Начав копать, Марлоу ввязывается в опасную и запутанную криминальную игру. Да и старшая дочь генерала Вивиан добавляет хлопот. Загадочная, жёсткая, непредсказуемая и сексапильная красавица постоянно оказывается там, где не надо.', 'Пожилой генерал Стернвуд нанимает частного детектива Филипа Марлоу, чтобы тот разобрался с шантажистами его распутной младшей дочери Кармен. Начав копать, Марлоу ввязывается в опасную и запутанную криминальную игру. Да и старшая дочь генерала Вивиан добавляет хлопот. Загадочная, жёсткая, непредсказуемая и сексапильная красавица постоянно оказывается там, где не надо.', '16+', 20000000, 100000000, 1946, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The type of man she hated . . . was the type she wanted !', 109, '1946-06-01'),
  ('844069a8-d98c-494b-af44-78c8ac988358', 'Новый кинотеатр «Парадизо»', 'Nuovo Cinema Paradiso', 'films/pic200.webp', 'posters/pic200.webp', 'Мальчик становится учеником киномеханика в послевоенной Сицилии. Атмосферная драма, удостоенная «Оскара»', 'Это рассказ о счастливых днях, когда итальянское кино еще не знало о том, что такое «кризис итальянского кинематографа». В центре разделенной как бы на три части картины - сицилийский мальчишка Сальваторе.', '16+', 1000000, 500000, 1988, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'A celebration of youth, friendship, and the everlasting magic of the movies.', 124, '1988-06-01'),
  ('2e4b13a9-33db-4288-b2b6-61cf5d14c515', 'Седьмая печать', 'Det sjunde inseglet', 'films/pic201.webp', 'posters/pic201.webp', 'Рыцарь играет в шахматы со Смертью в разгар чумы. Один из главных фильмов Бергмана — и мирового кинематографа', 'В середине XIV века рыцарь Антониус Блок и его оруженосец возвращаются после десяти лет крестовых походов в родную Швецию. Блок устал от жизни и не видит ничего, ради чего стоило бы продолжать влачить существование. Но прежде он хочет убедиться, что бог существует.', '18+', 300000000, 300000000, 1957, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'A film of visual scope, of imaginative concept, of powerful content, written and directed by Ingmar Bergman, twice honored by the Interational Jury at the Cannes Film Festival 1956,1957', 96, '1957-06-01'),
  ('a1dee25c-adbf-43ac-96f6-2128d8531164', 'Ребекка', 'Rebecca', 'films/pic202.webp', 'posters/pic202.webp', 'Призрак умершей жены аристократа не дает покоя его новой пассии. Шедевр Альфреда Хичкока с двумя «Оскарами»', 'Максимиллиан Де Уинтер - богатый мужчина, примерно год назад потерявший жену Ребекку. Он приезжает в Монте-Карло, где встречает миссис Ван Хоппер и её юную компаньонку. Постепенно Максимиллиан так увлекается молодой особой, что в конце концов женится на ней, и вскоре супруги возвращаются в Мэндэрли, владение семьи Де Уинтеров в Корнуэлле. Там девушку начинает преследовать и подавлять присутствие Ребекки, которое она видит абсолютно во всём.', '12+', 1000000, 2000000, 1940, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The shadow of a remembered woman came between their lips... but these two had the courage to hope... and to live their love!', 130, '1940-06-01'),
  ('d220c12d-0ecd-47a2-b538-edf228d7cb27', 'Доблесть', 'Glory', 'films/pic203.webp', 'posters/pic203.webp', 'Полковник Шоу был офицером армии Федералов во времена Гражданской войны в США. Он добровольно вызвался стать командиром первого в истории США подразделения чернокожих солдат. Полковник должен обучить их и повести в бой, но времени на подготовку слишком мало, а впереди — решающее сражение с регулярными войсками южан.', 'Полковник Шоу был офицером армии Федералов во времена Гражданской войны в США. Он добровольно вызвался стать командиром первого в истории США подразделения чернокожих солдат. Полковник должен обучить их и повести в бой, но времени на подготовку слишком мало, а впереди — решающее сражение с регулярными войсками южан.', NULL, 300000000, 150000000, 1989, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Their innocence. Their heritage. Their lives. Nothing would be spared in the fight for their freedom.', 122, '1989-06-01'),
  ('16165abd-095f-4c1a-9b90-cc5990b54777', 'Охотник на оленей', 'The Deer Hunter', 'films/pic204.webp', 'posters/pic204.webp', 'Трое друзей из русской общины проходят через войну и мир. Шедевр Майкла Чимино, получивший пять «Оскаров»', 'История о трех американцах русского происхождения — их жизни до, во время и после войны во Вьетнаме.', '18+', 1000000, 500000, 1978, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'One of the most important and powerful films of all time!', 183, '1978-06-01'),
  ('8a0157dd-e27a-436c-866b-d35c7aa789b5', 'Лучшие годы нашей жизни', 'The Best Years of Our Lives', 'films/pic205.webp', 'posters/pic205.webp', 'Трое боевых офицеров армии США возвращаются домой к близким. Эла Стивенсона ждут дома жена и двое подросших детей, и он пытается узнать их заново и вновь завоевать семейную любовь и доверие. По возвращению Эл получает повышение в банке, где он работал до войны.
Лётчик Фред Дерри возвращается к отдалившейся молодой жене, которую он едва знает. Фред понимает, что у него нет полезных в гражданской жизни навыков и снова устраивается на работу продавцом.
Моряка Хомера Пэрриша ждут семья и любимая ...', 'Трое боевых офицеров армии США возвращаются домой к близким. Эла Стивенсона ждут дома жена и двое подросших детей, и он пытается узнать их заново и вновь завоевать семейную любовь и доверие. По возвращению Эл получает повышение в банке, где он работал до войны.
Лётчик Фред Дерри возвращается к отдалившейся молодой жене, которую он едва знает. Фред понимает, что у него нет полезных в гражданской жизни навыков и снова устраивается на работу продавцом.
Моряка Хомера Пэрриша ждут семья и любимая девушка, на которой он обещал жениться по возвращению. Однако их чувствам предстоит пройти проверку на прочность, поскольку на войне он потерял обе руки.', '12+', 20000000, 100000000, 1946, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Filled with all the love and warmth and joy. . .the human heart can hold!', 170, '1946-06-01'),
  ('81fb31a9-3bd4-4f94-9b5a-b83b4baa4e58', 'Шрэк', 'Shrek', 'films/pic206.webp', 'posters/pic206.webp', 'Огр-мизантроп спасает принцессу, чтобы вернуть свое болото. Революционная анимация о том, что красота — внутри', 'Жил да был в сказочном государстве большой зеленый великан по имени Шрэк. Жил он в гордом одиночестве в лесу, на болоте, которое считал своим. Но однажды злобный коротышка — лорд Фаркуад, правитель волшебного королевства, безжалостно согнал на Шрэково болото всех сказочных обитателей.
И беспечной жизни зеленого великана пришел конец. Но лорд Фаркуад пообещал вернуть Шрэку болото, если великан добудет ему прекрасную принцессу Фиону, которая томится в неприступной башне, охраняемой огнедышащим драконом.', '18+', 200000000, 1600000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Its Big!', 90, '2001-06-01'),
  ('a65f0d53-98e9-4f9b-b2c9-1ea31ac483f6', 'Великий диктатор', 'The Great Dictator', 'films/pic207.webp', 'posters/pic207.webp', 'Главный герой фильма, еврейский цирюльник, сражается в рядах армии своего государства Томании. Однажды, во время одного из сражений, он спасает жизнь летчику Шульцу, но в результате довольно жесткого приземления ударяется головой, теряет память и долгое время находится в больнице.

Шли годы, война давно уже закончилась, и в Томании приходит к власти диктатор Аденоид Хинкель, который яро ненавидит евреев и очень сильно похож на того самого еврейского цирюльника. Хинкель жаждет завоевать весь м...', 'Главный герой фильма, еврейский цирюльник, сражается в рядах армии своего государства Томании. Однажды, во время одного из сражений, он спасает жизнь летчику Шульцу, но в результате довольно жесткого приземления ударяется головой, теряет память и долгое время находится в больнице.

Шли годы, война давно уже закончилась, и в Томании приходит к власти диктатор Аденоид Хинкель, который яро ненавидит евреев и очень сильно похож на того самого еврейского цирюльника. Хинкель жаждет завоевать весь мир, а в это время цирюльник выходит из больницы и, ни о чем не подозревая, пытается наладить старую жизнь. Однако впереди его ждут невероятные приключения…', '0+', 100000000, 100000000, 1940, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The Comedy Masterpiece!', 125, '1940-06-01'),
  ('bcbf539b-6b24-421e-ac52-a7ec96cf291a', 'Похитители велосипедов', 'Ladri di biciclette', 'films/pic208.webp', 'posters/pic208.webp', 'Антонио лишается единственной возможности прокормить сына. Один из важнейших фильмов в истории', 'Послевоенный Рим, давно неработающий Антонио вне себя от радости - он наконец-то находит работу. Но в первый же трудовой день у него украли велосипед, без которого невозможно работать! Вместе с маленьким сыном Бруно он пытается  найти  в огромном  городе украденный  велосипед,  от которого зависит жизнь его семьи...', '12+', 50000000, 500000000, 1948, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The Prize Picture They Want to Censor!', 89, '1948-06-01'),
  ('2b5deb2d-32f1-4184-80e3-c2a3f4c6e78a', 'Паттон', 'Patton', 'films/pic209.webp', 'posters/pic209.webp', 'По книгам «Паттон: испытания и триумф» и «История солдата» генерала Омара Н. Брэдли. Биография генерала Джорджа Паттона, чей темперамент часто оказывал влияние на ход военных действий во время второй мировой войны.', 'По книгам «Паттон: испытания и триумф» и «История солдата» генерала Омара Н. Брэдли. Биография генерала Джорджа Паттона, чей темперамент часто оказывал влияние на ход военных действий во время второй мировой войны.', '12+', 300000000, 1500000000, 1970, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Direct from its sensational reserved seat engagement.', 172, '1970-06-01'),
  ('146dde71-80e3-4a76-b555-1f041102ed73', 'Африканская королева', 'The African Queen', 'films/pic210.webp', 'posters/pic210.webp', '1914 год, Восточная Африка. Пропахший джином капитан Чарли приплывает на своем пароходике в деревню, где находится христианская миссия преподобного Сэмюэла и его незамужней сестры Розы, которые среди диких африканских джунглей ведут себя так, будто по-прежнему находятся в старой доброй Англии. Но война докатывается и до Африки.

Ворвавшиеся в миссию немецкие солдаты сжигают деревню и угоняют жителей. Пережитое плохо отразилось на состоянии преподобного, вскоре он умирает, а Розе приходится бе...', '1914 год, Восточная Африка. Пропахший джином капитан Чарли приплывает на своем пароходике в деревню, где находится христианская миссия преподобного Сэмюэла и его незамужней сестры Розы, которые среди диких африканских джунглей ведут себя так, будто по-прежнему находятся в старой доброй Англии. Но война докатывается и до Африки.

Ворвавшиеся в миссию немецкие солдаты сжигают деревню и угоняют жителей. Пережитое плохо отразилось на состоянии преподобного, вскоре он умирает, а Розе приходится бежать вместе с Чарли. Беспрерывно ссорясь друг с другом, чопорная миссионерка и бесшабашный капитан плывут по реке навстречу опасным и романтическим приключениям.', '0+', 20000000, 160000000, 1951, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The greatest adventure a man ever lived...with a woman!', 105, '1951-06-01'),
  ('7fb8c4d8-8929-4ee1-8cf4-800f1c7139e6', 'Зеленая миля', 'The Green Mile', 'films/pic211.webp', 'posters/pic211.webp', 'В тюрьме для смертников появляется заключенный с божественным даром. Мистическая драма по роману Стивена Кинга', 'Пол Эджкомб — начальник блока смертников в тюрьме «Холодная гора», каждый из узников которого однажды проходит «зеленую милю» по пути к месту казни. Пол повидал много заключённых и надзирателей за время работы. Однако гигант Джон Коффи, обвинённый в страшном преступлении, стал одним из самых необычных обитателей блока.', '18+', 100000000, 1000000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Пол Эджкомб не верил в чудеса. Пока не столкнулся с одним из них', 189, '1999-06-01'),
  ('1a98d876-b607-4135-ad6f-1d2b8d4a0e06', 'Бен-Гур', 'Ben-Hur', 'films/pic212.webp', 'posters/pic212.webp', 'Пока иудей-аристократ вершит месть, где-то рядом проповедует Христос. Эпос, собравший рекордные 11 «Оскаров»', 'Иерусалим, 26 год нашей эры. Два друга детства, иудей Бен-Гур и римский трибун Мессала, встречаются после долгой разлуки взрослыми людьми. Мессала просит назвать самых ярых противников власти Рима, но Бен-Гур не может предать собственный народ и отказывается, что приводит к конфликту. Вскоре Мессала, воспользовавшись обстоятельствами, решает отомстить бывшему другу и укрепить свою власть. По надуманному обвинению он бросает в тюрьму мать и сестру Бен-Гура, а его самого отправляет на галеры.', '0+', 20000000, 160000000, 1959, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The Entertainment Experience of a Lifetime!', 212, '1959-06-01'),
  ('2b126fa9-02af-4630-98d8-1327eae15942', 'Это случилось однажды ночью', 'It Happened One Night', 'films/pic213.webp', 'posters/pic213.webp', 'Элли собирается замуж за знаменитого летчика Кинга Вестли, но ее отец презирает того, считая светским бездельником, поэтому он сажает дочь под замок и ищет основания для аннулирования помолвки. Элли удается бежать, и она отправляется навстречу суженому в Нью-Йорк на автобусе. В том же автобусе едет только что уволенный репортер Питер. Ему необходима сенсация, чтобы восстановить отношения с редактором. В лице беглой наследницы миллионов, которую ищет полиция всей страны, судьба улыбается ему.', 'Элли собирается замуж за знаменитого летчика Кинга Вестли, но ее отец презирает того, считая светским бездельником, поэтому он сажает дочь под замок и ищет основания для аннулирования помолвки. Элли удается бежать, и она отправляется навстречу суженому в Нью-Йорк на автобусе. В том же автобусе едет только что уволенный репортер Питер. Ему необходима сенсация, чтобы восстановить отношения с редактором. В лице беглой наследницы миллионов, которую ищет полиция всей страны, судьба улыбается ему.', '12+', 100000000, 500000000, 1934, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Together for the first time!', 105, '1934-06-01'),
  ('359a688d-0a6f-470f-b08a-720347be83c4', 'Филадельфийская история', 'The Philadelphia Story', 'films/pic214.webp', 'posters/pic214.webp', 'Трейси влюбляется в репортера, пишущего о ее свадьбе. Классика ромкома с Кэри Грантом и Кэтрин Хепберн', 'Холодная красавица миссис Трейси разведена и готовится вновь выйти замуж за Джорджа, управляющего нефтяной компанией ее отца. Казалось бы, сомнений нет, но вдруг накануне торжества неожиданно появляется ее бывший муж Декстер в сопровождении двух корреспондентов - симпатичного молодого человека по имени Коннор и мисс Имбири - которые должны осветить в желтой прессе это светское событие.', '12+', 1000000, 1000000, 1940, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'The 3-Star Laugh Hit!', 112, '1940-06-01'),
  ('cda9b70b-3f8f-422f-8885-08013059eeca', 'Город бога', 'Cidade de Deus', 'films/pic215.webp', 'posters/pic215.webp', 'Можно ли родиться гангстером? Шокирующее погружение в пестрый и опасный мир бразильских фавел', 'Город Бога — самая опасная фавела Рио-де-Жанейро, и именно здесь растут трое детей: Ракета, Малыш Фишка и Бенни. Поначалу они только наблюдают, как другие подростки грабят мотели и мелкие лавки, но круговорот насилия затягивает и их. Фишка — теперь Малыш Зе, главный наркоторговец и гроза всего района. Бенни — его лучший друг и правая рука, но его тяготит криминальный образ жизни. И только Ракете удается оставаться в стороне. Он мечтает стать фотографом и становится свидетелем и собирателем хроники гангстерских разборок, утопивших Город Бога в крови.', '18+', 100000000, 300000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Бейся или не выживешь... Гони или никогда не сбежишь...', 130, '2002-06-01'),
  ('f81e3ebf-9aa7-4906-b90d-cae97cce0c81', 'Воспитание Крошки', 'Bringing Up Baby', 'films/pic216.webp', 'posters/pic216.webp', 'Бойкая красавица влюбляется в одержимого работой ученого. Затейливый ромком с Кэтрин Хепберн и Кэри Грантом', 'Дэвид Хаксли — чудаковатый палеонтолог, последние четыре года жизни по косточке воссоздающий скелет бронтозавра. За день до свадьбы злодейка-судьба сталкивает его со Сьюзан, неуемной молодой девицей, которая тут же положила на него глаз и начала причинять бесконечные неприятности, пытаясь заполучить его.', '18+', 1000000, 2000000, 1938, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'And so begins the hilarious adventure of Professor David Huxley and Miss Susan Vance, a flutter-brained vixen with love in her heart!', 102, '1938-06-01'),
  ('460450d1-6021-4f92-8a8b-059cba9b02c0', 'Принцесса Мононоке', 'Mononoke-hime', 'films/pic217.webp', 'posters/pic217.webp', 'Заколдованный принц и лесная принцесса борются с древним демоном и его рабами. Аниме-блокбастер Хаяо Миядзаки', 'Убив вепря, юный принц Аситака навлек на себя смертельное проклятие. Старая знахарка предсказала, что только он сам способен изменить свою судьбу, и отважный воин отправился в опасное путешествие. Так он оказался в загадочной стране, где люди под предводительством злой госпожи Эбоси воевали с обитателями леса: духами, демонами и гигантскими существами, каких Аситака раньше никогда не видел. 
И была с ними принцесса Мононоке - повелительница зверей и дочь волчицы. Теперь судьба всех зависит только от одного воина - принца Аситаки.', '12+', 20000000, 100000000, 1997, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a15', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Live on.', 133, '1997-06-01'),
  ('f92ac041-9747-471e-b007-9e91529969f0', 'Простая история', 'The Straight Story', 'films/pic218.webp', 'posters/pic218.webp', 'Старик на газонокосилке едет к заболевшему брату через два штата. Самый добрый и понятный фильм Дэвида Линча', '73-летний Элвин Стрэйт, испытывающий проблемы со здоровьем, живёт с дочерью Роуз в тихом провинциальном городке Лоренс, штат Айова. Однажды он узнаёт, что у его брата Лайла, живущего в штате Висконсин, с которым после ссоры он не общался 10 лет, случился инфаркт. Элвин решает навестить брата, но поскольку водительских прав у него нет, а ехать на автобусе упрямый старик не желает, он покупает подержанную газонокосилку и отправляется в путь протяжённостью почти 500 километров.', '12+', 100000000, 200000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Ничто не может противостоять человеческой воле...', 112, '1999-06-01'),
  ('18cf2e91-369e-481a-8fb5-b8c3d4ddd7c5', 'Хладнокровный Люк', 'Cool Hand Luke', 'films/pic219.webp', 'posters/pic219.webp', 'Однажды ночью выпив, Люк решил развлечься и свинтил газовым ключом дюжину монетоприемников на автостоянке, за что и получил два года ремонтно-строительных работ на дорогах в южных штатах. Еще во время войны он много раз испытывал свою судьбу на прочность, и тюрьма стала очередной проверкой, которую Люк, похоже, и искал.', 'Однажды ночью выпив, Люк решил развлечься и свинтил газовым ключом дюжину монетоприемников на автостоянке, за что и получил два года ремонтно-строительных работ на дорогах в южных штатах. Еще во время войны он много раз испытывал свою судьбу на прочность, и тюрьма стала очередной проверкой, которую Люк, похоже, и искал.', '16+', 5000000, 5000000, 1967, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', '"What we''ve got here is failure to communicate."', 126, '1967-06-01'),
  ('b05300d5-ba4b-4902-9bdf-67e4feb83c83', 'Терминатор 2: Судный день', 'Terminator 2: Judgment Day', 'films/pic220.webp', 'posters/pic220.webp', 'Жидкий киборг, ядерный апокалипсис и культовое «Hasta la vista, baby». Бессмертный шедевр Джеймса Кэмерона', 'Прошло более десяти лет с тех пор, как киборг из 2029 года пытался уничтожить Сару Коннор — женщину, чей будущий сын выиграет войну человечества против машин.

Теперь у Сары родился сын Джон и время, когда он поведёт за собой выживших людей на борьбу с машинами, неумолимо приближается. Именно в этот момент из постапокалиптического будущего прибывает новый терминатор — практически неуязвимая модель T-1000, способная принимать любое обличье. Цель нового терминатора уже не Сара, а уничтожение молодого Джона Коннора.

Однако шансы Джона на спасение существенно повышаются, когда на помощь приходит перепрограммированный сопротивлением терминатор предыдущего поколения. Оба киборга вступают в смертельный бой, от исхода которого зависит судьба человечества.', '18+', 300000000, 600000000, 1991, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Same Make. Same Model. New Mission', 137, '1991-06-01')
ON CONFLICT (title, year) DO NOTHING;

